	root := t.TempDir()
	if err := os.Chmod(root, 0o700); err != nil {
		t.Fatal(err)
	}
	fixture := exec.CommandContext(t.Context(), "go", "run", "jwtsetup/main.go",
		"--dir", root, "--cell", "lab", "--brokers", "c1,c2,c3", "--host-node", "host-a")
