func writeFixtureFiles(directory string, names []string, files map[string][]byte) (err error) {
	created := make([]string, 0, len(names))
	defer func() {
		if err == nil {
			return
		}
		for _, path := range created {
			_ = os.Remove(path)
		}
	}()
	for _, name := range names {
		contents, exists := files[name]
		if !exists {
			return fmt.Errorf("fixture output %s was not generated", name)
		}
		path := filepath.Join(directory, name)
		file, openErr := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
		if openErr != nil {
			return fmt.Errorf("create fixture output %s: %w", name, openErr)
		}
		created = append(created, path)
		if chmodErr := file.Chmod(0o600); chmodErr != nil {
			_ = file.Close()
			return fmt.Errorf("secure fixture output %s: %w", name, chmodErr)
		}
		if _, writeErr := file.Write(contents); writeErr != nil {
			_ = file.Close()
			return fmt.Errorf("write fixture output %s: %w", name, writeErr)
		}
		if syncErr := file.Sync(); syncErr != nil {
			_ = file.Close()
			return fmt.Errorf("sync fixture output %s: %w", name, syncErr)
		}
		if closeErr := file.Close(); closeErr != nil {
			return fmt.Errorf("close fixture output %s: %w", name, closeErr)
		}
	}
	directoryFile, err := os.Open(directory)
	if err != nil {
		return fmt.Errorf("open secrets directory for sync: %w", err)
	}
	defer directoryFile.Close()
	if err := directoryFile.Sync(); err != nil {
		return fmt.Errorf("sync secrets directory: %w", err)
	}
	return nil
}

func NewCapturingObjectStorage(now time.Time) (*CapturingObjectStorage, error) {
	if now.IsZero() || now.Location() != time.UTC {
		return nil, errors.New("capture clock must be a fixed UTC instant")
	}
	return &CapturingObjectStorage{now: now.Truncate(time.Second), objects: make(map[capturedKey]CapturedObject),
		misses: make(map[capturedKey]struct{})}, nil
}

func (store *CapturingObjectStorage) PutObject(_ context.Context, request objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error) {
	if request.NamespaceName == nil || request.BucketName == nil || request.ObjectName == nil ||
		request.PutObjectBody == nil || request.ContentLength == nil || *request.ContentLength < 0 ||
		*request.ContentLength > 64<<10 || request.OpcSseKmsKeyId == nil ||
		request.OpcChecksumAlgorithm != objectstorage.PutObjectOpcChecksumAlgorithmSha256 ||
		request.OpcContentSha256 == nil || request.IfNoneMatch == nil && request.IfMatch == nil ||
		request.IfNoneMatch != nil && request.IfMatch != nil {
		return objectstorage.PutObjectResponse{}, errors.New("capture rejected noncanonical ledger PUT")
	}
	defer request.PutObjectBody.Close()
	body, err := io.ReadAll(io.LimitReader(request.PutObjectBody, 64<<10+1))
	if err != nil || int64(len(body)) != *request.ContentLength {
		return objectstorage.PutObjectResponse{}, errors.New("capture rejected ledger PUT content length")
	}
	digest := sha256.Sum256(body)
	if *request.OpcContentSha256 != base64.StdEncoding.EncodeToString(digest[:]) {
		return objectstorage.PutObjectResponse{}, errors.New("capture rejected ledger PUT SHA-256")
	}
	key := capturedKey{*request.NamespaceName, *request.BucketName, *request.ObjectName}
	store.mu.Lock()
	defer store.mu.Unlock()
	previous, exists := store.objects[key]
	if request.IfNoneMatch != nil && (*request.IfNoneMatch != "*" || exists) ||
		request.IfMatch != nil && (!exists || *request.IfMatch != previous.ETag) {
		return objectstorage.PutObjectResponse{}, captureServiceError{http.StatusPreconditionFailed}
	}
	if len(store.objects) >= 512 && !exists {
		return objectstorage.PutObjectResponse{}, errors.New("capture object bound exceeded")
	}
	store.version++
	store.puts++
	etag := fmt.Sprintf("\"%s-%d\"", hex.EncodeToString(digest[:8]), store.version)
	store.objects[key] = CapturedObject{Namespace: key.namespace, Bucket: key.bucket, ObjectName: key.object,
		Body: bytes.Clone(body), ETag: etag, LastModified: store.now}
	return objectstorage.PutObjectResponse{ETag: new(etag), OpcRequestId: new("fixture-capture-put")}, nil
}

func (store *CapturingObjectStorage) GetObject(_ context.Context, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	if request.NamespaceName == nil || request.BucketName == nil || request.ObjectName == nil {
		return objectstorage.GetObjectResponse{}, errors.New("capture rejected incomplete exact-key GET")
	}
	key := capturedKey{*request.NamespaceName, *request.BucketName, *request.ObjectName}
	store.mu.Lock()
	object, exists := store.objects[key]
	if !exists {
		if _, seen := store.misses[key]; !seen && len(store.misses) >= 512 {
			store.mu.Unlock()
			return objectstorage.GetObjectResponse{}, errors.New("capture expected-missing route bound exceeded")
		}
		store.misses[key] = struct{}{}
	}
	now := store.now
	store.mu.Unlock()
	if !exists {
		return objectstorage.GetObjectResponse{}, captureServiceError{http.StatusNotFound}
	}
	responseHeaders := make(http.Header)
	responseHeaders.Set("Date", now.Format(http.TimeFormat))
	length := int64(len(object.Body))
	return objectstorage.GetObjectResponse{RawResponse: &http.Response{Header: responseHeaders},
		Content: io.NopCloser(bytes.NewReader(object.Body)), ContentLength: &length, ETag: new(object.ETag),
		LastModified: &common.SDKTime{Time: object.LastModified}, OpcRequestId: new("fixture-capture-get")}, nil
}

// MissingSnapshot returns exact keys that were read as absent during the
// production Ledger workflow and remain absent after fixture construction.
func (store *CapturingObjectStorage) MissingSnapshot() []CapturedMissing {
	store.mu.Lock()
	defer store.mu.Unlock()
	missing := make([]CapturedMissing, 0, len(store.misses))
	for key := range store.misses {
		if _, exists := store.objects[key]; !exists {
			missing = append(missing, CapturedMissing{Namespace: key.namespace, Bucket: key.bucket, ObjectName: key.object})
		}
	}
	slices.SortFunc(missing, func(a, b CapturedMissing) int {
		return bytes.Compare([]byte(a.Namespace+"\x00"+a.Bucket+"\x00"+a.ObjectName),
			[]byte(b.Namespace+"\x00"+b.Bucket+"\x00"+b.ObjectName))
	})
	return missing
}

type CapturedMissing struct {
	Namespace  string
	Bucket     string
	ObjectName string
}

func (store *CapturingObjectStorage) Snapshot() []CapturedObject {
	store.mu.Lock()
	defer store.mu.Unlock()
	objects := make([]CapturedObject, 0, len(store.objects))
	for _, object := range store.objects {
		object.Body = bytes.Clone(object.Body)
		objects = append(objects, object)
	}
	slices.SortFunc(objects, func(a, b CapturedObject) int {
		return bytes.Compare([]byte(a.Namespace+"\x00"+a.Bucket+"\x00"+a.ObjectName),
			[]byte(b.Namespace+"\x00"+b.Bucket+"\x00"+b.ObjectName))
	})
	return objects
}

func (store *CapturingObjectStorage) PutCount() uint64 {
	store.mu.Lock()
	defer store.mu.Unlock()
	return store.puts
}

type captureServiceError struct{ status int }

func (err captureServiceError) Error() string {
	return fmt.Sprintf("captured Object Storage status %d", err.status)
}
func (err captureServiceError) GetHTTPStatusCode() int  { return err.status }
func (err captureServiceError) GetMessage() string      { return err.Error() }
func (err captureServiceError) GetCode() string         { return "FixtureCapture" }
func (err captureServiceError) GetOpcRequestID() string { return "fixture-capture" }

func BuildCapturedInventory(anchor bootstrap.VerifiedBootstrapAnchor, controllers []Controller,
	store *CapturingObjectStorage,
) (CapturedInventory, error) {
	if !anchor.IsVerified() || store == nil || store.PutCount() == 0 || len(controllers) != 3 {
		return CapturedInventory{}, errors.New("capture inventory requires verified anchor, ledger writes, and three controllers")
	}
	anchored := anchor.Anchor()
	if anchored.Environment != "production" || string(anchored.Cell) != "GRU" ||
		!slices.Equal(anchored.ControllerSlots, []string{"controller-a", "controller-b", "controller-c"}) {
		return CapturedInventory{}, errors.New("capture inventory anchor is outside production GRU three-slot scope")
	}
	domain := anchor.StorageDomain()
	if err := domain.Validate(); err != nil {
		return CapturedInventory{}, err
	}
	for index, controller := range controllers {
		if controller.Slot != anchored.ControllerSlots[index] ||
			controller.GuestRoot != "controllers/"+controller.Slot+"/guest-root" ||
			!strings.HasPrefix(controller.InstanceOCID, "ocid1.instance.oc1.sa-saopaulo-1.") {
			return CapturedInventory{}, fmt.Errorf("capture controller %q differs from anchored slot topology", controller.Slot)
		}
		for previous := range index {
			if controllers[previous].InstanceOCID == controller.InstanceOCID {
				return CapturedInventory{}, errors.New("capture controllers share one OCI instance identity")
			}
		}
	}
	validKey := func(namespace, bucket, name string) bool {
		return namespace == domain.Namespace &&
			(bucket == domain.LedgerBucket || bucket == domain.HeadBucket) && name != "" &&
			(domain.Prefix == "" || strings.HasPrefix(name, domain.Prefix+"/"))
	}
	objects := store.Snapshot()
	missing := store.MissingSnapshot()
	if len(objects)+len(missing) == 0 || 3*(len(objects)+len(missing)) > 512 {
		return CapturedInventory{}, errors.New("captured object inventory exceeds simulator route bound")
	}
	inventory := CapturedInventory{Bodies: make(map[string][]byte, len(objects))}
	for _, controller := range controllers {
		for _, object := range objects {
			if !validKey(object.Namespace, object.Bucket, object.ObjectName) {
				return CapturedInventory{}, errors.New("captured object escaped anchored private storage domain")
			}
			route, err := CapturedObjectRoute(controller, object)
			if err != nil {
				return CapturedInventory{}, err
			}
			if previous, ok := inventory.Bodies[route.BodyPath]; ok && !bytes.Equal(previous, object.Body) {
				return CapturedInventory{}, errors.New("captured response digest path has different bytes")
			}
			inventory.Bodies[route.BodyPath] = bytes.Clone(object.Body)
			inventory.Routes = append(inventory.Routes, route)
		}
		for _, absent := range missing {
			if !validKey(absent.Namespace, absent.Bucket, absent.ObjectName) {
				return CapturedInventory{}, errors.New("captured missing key escaped anchored private storage domain")
			}
			route, err := CapturedMissingRoute(controller, absent)
			if err != nil {
				return CapturedInventory{}, err
			}
			inventory.Routes = append(inventory.Routes, route)
		}
	}
	slices.SortFunc(inventory.Routes, func(a, b Route) int {
		return strings.Compare(a.ControllerSlot+"\n"+a.InstanceOCID+"\n"+a.Host+"\n"+a.RequestURI,
			b.ControllerSlot+"\n"+b.InstanceOCID+"\n"+b.Host+"\n"+b.RequestURI)
	})
	return inventory, nil
}

func verifiedCaptureAnchor(t *testing.T, now time.Time) (bootstrap.VerifiedBootstrapAnchor, trust.Keyring) {
	t.Helper()
	rootPublic, rootPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	delegatePublic, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(rootPublic)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(delegatePublic)
	if err != nil {
		t.Fatal(err)
	}
	publicWire, err := trust.EncodeDelegatedPublicKey(delegatePublic)
	if err != nil {
		t.Fatal(err)
	}
	slots := []string{"controller-a", "controller-b", "controller-c"}
	var capabilities []trust.Capability
	for _, domain := range bootstrap.BootstrapLedgerCapabilityDomains() {
		capabilities = append(capabilities, trust.Capability{Domain: domain, DeploymentID: "0000000000F9PR1WNVDTEXS31Z",
			Cell: "GRU", Environment: "production", Role: "controller", Slots: slots, Actions: []string{"sign"}})
	}
	grant, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion,
		SubjectKeyID: keyID, SubjectPublicKey: publicWire, Capabilities: capabilities},
		now.Add(-time.Minute), now.Add(23*time.Hour), rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	grantWire, err := trust.EncodeEnvelope(grant)
	if err != nil {
		t.Fatal(err)
	}
	regionWire, err := trust.EncodePayload(oci.RegionIntent{SchemaVersion: 1, Generation: 1,
		BootstrapRegion: oci.RegionGRU, Regions: []oci.RegionMapping{{Cell: oci.RegionGRU, OCIRegion: "sa-saopaulo-1"}}})
	if err != nil {
		t.Fatal(err)
	}
	digest := sha256.Sum256(regionWire)
	anchor := bootstrap.BootstrapAnchor{SchemaVersion: bootstrap.BootstrapAnchorSchemaVersion,
		DeploymentID: "0000000000F9PR1WNVDTEXS31Z", Environment: "production", ClusterID: "0000000000RMSAJ9B0JFV7ESHN", Cell: oci.RegionGRU,
		OCIRegion: "sa-saopaulo-1", ControllerSlots: slots, LedgerDelegationWire: grantWire,
		StorageDomain: bootstrap.StorageDomain{Namespace: "namespace-a", LedgerBucket: "ledger-bucket",
			LedgerKMSKeyOCID: "ocid1.key.oc1.sa-saopaulo-1.ledger", HeadBucket: "head-bucket",
			HeadKMSKeyOCID: "ocid1.key.oc1.sa-saopaulo-1.head", Prefix: "private/bootstrap"},
		InitialRegionIntentGeneration: 1, InitialRegionIntentSHA256: hex.EncodeToString(digest[:]),
		InitialRegionIntentWire: regionWire}
	envelope, err := bootstrap.SignBootstrapAnchor(anchor, now, now.Add(22*time.Hour), rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	verified, err := bootstrap.VerifyBootstrapAnchor(envelope, roots,
		bootstrap.BootstrapAnchorExpectation{DeploymentID: anchor.DeploymentID, Environment: anchor.Environment,
			Cell: anchor.Cell}, now, trust.Policy{MaxLifetime: 24 * time.Hour, ClockSkew: time.Minute})
	if err != nil {
		t.Fatal(err)
	}
	return verified, roots
}

func CapturedObjectRoute(controller Controller, object CapturedObject) (Route, error) {
	if controller.Slot == "" || controller.InstanceOCID == "" || object.Namespace == "" ||
		object.Bucket == "" || object.ObjectName == "" || len(object.Body) == 0 ||
		object.ETag == "" || object.LastModified.IsZero() {
		return Route{}, errors.New("captured object lacks route identity or response metadata")
	}
	uri, err := sdkObjectRequestURI(object.Namespace, object.Bucket, object.ObjectName)
	if err != nil {
		return Route{}, err
	}
	digest := sha256.Sum256(object.Body)
	return Route{ControllerSlot: controller.Slot, InstanceOCID: controller.InstanceOCID,
		Host: "objectstorage.sa-saopaulo-1.oraclecloud.com", RequestURI: uri,
		Status: http.StatusOK, BodyPath: "simulator/responses/" + hex.EncodeToString(digest[:]) + ".json",
		ETag: object.ETag, LastModified: object.LastModified}, nil
}

func CapturedMissingRoute(controller Controller, missing CapturedMissing) (Route, error) {
	if controller.Slot == "" || controller.InstanceOCID == "" || missing.Namespace == "" ||
		missing.Bucket == "" || missing.ObjectName == "" {
		return Route{}, errors.New("captured missing read lacks exact identity")
	}
	uri, err := sdkObjectRequestURI(missing.Namespace, missing.Bucket, missing.ObjectName)
	if err != nil {
		return Route{}, err
	}
	return Route{ControllerSlot: controller.Slot, InstanceOCID: controller.InstanceOCID,
		Host: "objectstorage.sa-saopaulo-1.oraclecloud.com", RequestURI: uri,
		Status: http.StatusNotFound}, nil
}

func sdkObjectRequestURI(namespace, bucket, objectName string) (string, error) {
	request, err := (objectstorage.GetObjectRequest{NamespaceName: new(namespace),
		BucketName: new(bucket), ObjectName: new(objectName)}).HTTPRequest(
		http.MethodGet, "/n/{namespaceName}/b/{bucketName}/o/{objectName}", nil, nil)
	if err != nil {
		return "", fmt.Errorf("construct OCI SDK exact object GET: %w", err)
	}
	return request.URL.RequestURI(), nil
}

func rejectKeyInsideMaterial(materialRoot, privatePath string) error {
	material, err := filepath.EvalSymlinks(materialRoot)
	if err != nil {
		return err
	}
	material, err = filepath.Abs(material)
	if err != nil {
		return err
	}
	private, err := filepath.EvalSymlinks(privatePath)
	if err != nil {
		return err
	}
	private, err = filepath.Abs(private)
	if err != nil {
		return err
	}
	relative, err := filepath.Rel(material, private)
	if err != nil {
		return err
	}
	if relative == "." || relative != ".." && !strings.HasPrefix(relative, ".."+string(os.PathSeparator)) {
		return errors.New("offline root signing key must be outside packet material tree")
	}
	return nil
}

func EmitCompletedRestartPacket(ctx context.Context, destination, sourceRoot string,
	manifest Manifest, prepareMaterial MaterialPreparer, anchor bootstrap.VerifiedBootstrapAnchor,
	capture *CapturingObjectStorage, prepare HistoryPreparer, packetRootKey ed25519.PrivateKey,
	roots trust.Keyring, expiresAt time.Time,
) (VerifiedPacket, CompletedHistories, error) {
	if !anchor.IsVerified() || capture == nil || prepare == nil || prepareMaterial == nil {
		return VerifiedPacket{}, CompletedHistories{}, errors.New("complete packet requires verified anchor, history, and material preparers")
	}
	anchored := anchor.Anchor()
	if manifest.DeploymentID != anchored.DeploymentID || manifest.Cell != string(anchored.Cell) ||
		manifest.Environment != anchored.Environment || len(manifest.Controllers) != len(anchored.ControllerSlots) {
		return VerifiedPacket{}, CompletedHistories{}, errors.New("packet identity differs from verified anchor")
	}
	for index, controller := range manifest.Controllers {
		if controller.Slot != anchored.ControllerSlots[index] {
			return VerifiedPacket{}, CompletedHistories{}, errors.New("packet controller slot differs from verified anchor")
		}
	}
	if err := VerifyCompletedSourcePins(sourceRoot, manifest.SourcePins); err != nil {
		return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("completed recipe source binding: %w", err)
	}
	for _, route := range manifest.Routes {
		if route.Host != "iaas.sa-saopaulo-1.oraclecloud.com" {
			return VerifiedPacket{}, CompletedHistories{}, errors.New("prepared route inventory may contain only Compute reads")
		}
	}
	capture.mu.Lock()
	captureNow := capture.now
	captureStarted := capture.puts != 0 || len(capture.objects) != 0 || len(capture.misses) != 0
	capture.mu.Unlock()
	if captureStarted || !captureNow.Equal(manifest.FixtureNow.Truncate(time.Second)) {
		return VerifiedPacket{}, CompletedHistories{}, errors.New("completed recipe requires an empty capture at the fixture clock")
	}
	grant, err := anchor.LedgerDelegation()
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, err
	}
	domain := anchor.StorageDomain()
	config := bootstrap.LedgerConfig{
		DeploymentID: anchored.DeploymentID, Cell: anchored.Cell, ClusterID: anchored.ClusterID,
		InitialRegionIntentGeneration: anchored.InitialRegionIntentGeneration,
		InitialRegionIntentSHA256:     anchored.InitialRegionIntentSHA256,
		Namespace:                     domain.Namespace, Bucket: domain.LedgerBucket, KMSKeyID: domain.LedgerKMSKeyOCID,
		Prefix: domain.Prefix, HeadBucket: domain.HeadBucket, HeadKMSKeyID: domain.HeadKMSKeyOCID,
		Environment: anchored.Environment, ControllerSlots: slices.Clone(anchored.ControllerSlots),
		AnchorExpiresAt: anchor.ExpiresAt(), TrustRoots: roots, Delegations: []trust.VerifiedDelegation{grant},
		TrustPolicy: bootstrap.BootstrapAnchorTrustPolicy(), VerificationNow: func() time.Time { return captureNow },
	}
	ledger, err := bootstrap.NewLedger(capture, config)
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("open capture-backed public ledger: %w", err)
	}
	seed, peers, err := prepare(ledger)
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("prepare signed histories: %w", err)
	}
	if seed.Scope.Slot != "controller-c" || len(peers) != 2 ||
		!slices.ContainsFunc(peers, func(peer ManagedHistory) bool { return peer.Scope.Slot == "controller-a" }) ||
		!slices.ContainsFunc(peers, func(peer ManagedHistory) bool { return peer.Scope.Slot == "controller-b" }) {
		return VerifiedPacket{}, CompletedHistories{}, errors.New("completed packet requires controller-c external seed and both controller slots as managed peers")
	}
	completed, err := BuildCompletedHistories(ctx, ledger, seed, peers)
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, err
	}
	historical, err := bootstrap.NewHistoricalLedger(capture, config)
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("open production-style historical reader: %w", err)
	}
	for _, peer := range peers {
		state, err := historical.ReadSlot(ctx, peer.Scope)
		if err != nil || state.Result == nil || state.ResultRecord == nil || state.PeerReceiptRecord == nil ||
			state.Head.ResultDigest == "" || state.Head.ResultDigest != state.ResultRecord.SHA256 ||
			state.Intent.Mode != bootstrap.IntentModeManaged || state.Result.Mode != bootstrap.IntentModeManaged ||
			state.Head.Attempt != state.Intent.Attempt || state.Head.Attempt != state.Result.Attempt ||
			state.Intent.Slot != peer.Scope.Slot || state.Result.Slot != peer.Scope.Slot ||
			state.Intent.DeploymentID != peer.Scope.DeploymentID || state.Result.DeploymentID != peer.Scope.DeploymentID ||
			state.Intent.Cell != peer.Scope.Cell || state.Result.Cell != peer.Scope.Cell {
			return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("historical founder peer %q is not completed: %w", peer.Scope.Slot, err)
		}
	}
	if completed.Seed.Manifest == nil || completed.Seed.Result == nil {
		return VerifiedPacket{}, CompletedHistories{}, errors.New("verified seed history lacks image or instance identity")
	}
	imageOCID := completed.Seed.Manifest.ImageOCID
	for _, controller := range manifest.Controllers {
		state := completed.Seed
		if controller.Slot != seed.Scope.Slot {
			var exists bool
			state, exists = completed.Peers[controller.Slot]
			if !exists {
				return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("controller %q has no completed history", controller.Slot)
			}
		}
		if state.Result == nil || state.Result.InstanceOCID != controller.InstanceOCID ||
			state.Manifest == nil || state.Manifest.ImageOCID != imageOCID ||
			!bytes.Equal(state.Manifest.ReleaseImageReceiptWire, completed.Seed.Manifest.ReleaseImageReceiptWire) ||
			!bytes.Equal(state.Manifest.ReleaseDelegationWire, completed.Seed.Manifest.ReleaseDelegationWire) {
			return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("controller %q has different positive OCI or image identity", controller.Slot)
		}
	}
	putsBeforeMaterial := capture.PutCount()
	prepared, err := prepareMaterial(ctx, completed)
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("prepare verified guest material: %w", err)
	}
	if capture.PutCount() != putsBeforeMaterial {
		return VerifiedPacket{}, CompletedHistories{}, errors.New("guest material preparation wrote to the ledger capture")
	}
	if _, err := parseGuestDirectories(prepared[guestDirectoryPlanPath], manifest.Controllers,
		func(path string) bool { _, ok := prepared[path]; return ok }); err != nil {
		return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("completed packet guest directory contract: %w", err)
	}
	inventory, err := BuildCapturedInventory(anchor, manifest.Controllers, capture)
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, err
	}
	material := make(map[string][]byte, len(prepared)+len(inventory.Bodies)+2)
	for name, body := range prepared {
		material[name] = bytes.Clone(body)
	}
	for name, body := range inventory.Bodies {
		if old, exists := material[name]; exists && !bytes.Equal(old, body) {
			return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("captured Object Storage body conflicts with prepared material %q", name)
		}
		material[name] = bytes.Clone(body)
	}
	for name, body := range map[string][]byte{
		"simulator/release-image-receipt.json": completed.Seed.Manifest.ReleaseImageReceiptWire,
		"simulator/release-delegation.json":    completed.Seed.Manifest.ReleaseDelegationWire,
	} {
		if old, exists := material[name]; exists && !bytes.Equal(old, body) {
			return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("signed release proof conflicts with prepared material %q", name)
		}
		material[name] = bytes.Clone(body)
	}
	manifest.Routes = append(slices.Clone(manifest.Routes), inventory.Routes...)
	slices.SortFunc(manifest.Routes, func(a, b Route) int {
		return strings.Compare(a.ControllerSlot+"\n"+a.InstanceOCID+"\n"+a.Host+"\n"+a.RequestURI,
			b.ControllerSlot+"\n"+b.InstanceOCID+"\n"+b.Host+"\n"+b.RequestURI)
	})
	for name := range material {
		if !strings.HasPrefix(name, "simulator/responses/") {
			continue
		}
		if !slices.ContainsFunc(manifest.Routes, func(route Route) bool { return route.BodyPath == name }) {
			return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("unreferenced simulator response %q", name)
		}
	}
	if _, err := os.Lstat(destination); err == nil || !errors.Is(err, os.ErrNotExist) {
		return VerifiedPacket{}, CompletedHistories{}, errors.New("completed packet destination must not exist")
	}
	parent := filepath.Dir(destination)
	if err := os.MkdirAll(parent, 0o700); err != nil {
		return VerifiedPacket{}, CompletedHistories{}, err
	}
	stagingRoot, err := os.MkdirTemp(parent, ".completed-packet-")
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, err
	}
	defer os.RemoveAll(stagingRoot)
	staging := filepath.Join(stagingRoot, "packet")
	packet, err := EmitPacket(staging, sourceRoot, manifest, material, packetRootKey, roots, expiresAt)
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, err
	}
	if _, err := VerifyPacketEmbeddedImage(packet, roots, imageOCID, time.Now().UTC()); err != nil {
		return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("completed packet image binding: %w", err)
	}
	if err := packet.ValidateProductionGuests(time.Now().UTC()); err != nil {
		return VerifiedPacket{}, CompletedHistories{}, fmt.Errorf("completed packet production guest boundary: %w", err)
	}
	if err := unix.Renameat2(unix.AT_FDCWD, staging, unix.AT_FDCWD, destination, unix.RENAME_NOREPLACE); err != nil {
		return VerifiedPacket{}, CompletedHistories{}, err
	}
	packet, err = ValidatePacket(destination, roots, time.Now().UTC())
	if err != nil {
		return VerifiedPacket{}, CompletedHistories{}, err
	}
	return packet, completed, nil
}

func BuildCompletedHistories(ctx context.Context, ledger *bootstrap.Ledger,
	seed SeedHistory, peers []ManagedHistory,
) (CompletedHistories, error) {
	if ledger == nil || seed.Scope.Slot == "" || len(peers) != 2 ||
		peers[0].Scope.Slot == "" || peers[1].Scope.Slot == "" ||
		peers[0].Scope.Slot == peers[1].Scope.Slot ||
		peers[0].Scope.Slot == seed.Scope.Slot || peers[1].Scope.Slot == seed.Scope.Slot {
		return CompletedHistories{}, errors.New("restart fixture needs one seed and two distinct managed slots")
	}
	if _, err := ledger.ReserveSlot(ctx, seed.Scope, seed.IntentWire, seed.ReservedHeadWire); err != nil {
		return CompletedHistories{}, fmt.Errorf("reserve seed slot: %w", err)
	}
	for _, peer := range peers {
		if _, err := ledger.ReserveSlot(ctx, peer.Scope, peer.IntentWire, peer.ReservedHeadWire); err != nil {
			return CompletedHistories{}, fmt.Errorf("reserve managed slot %s: %w", peer.Scope.Slot, err)
		}
	}
	if _, err := ledger.RecordExternalSeed(ctx, seed.Scope, seed.ManifestWire, seed.ReceiptWire,
		seed.Facts, seed.ResultWire, seed.CompletedHeadWire); err != nil {
		return CompletedHistories{}, fmt.Errorf("complete seed slot: %w", err)
	}
	for _, peer := range peers {
		if err := ledger.RecordManagedPeerCandidate(ctx, peer.Scope, peer.CandidateWire,
			peer.SignProgress, peer.Refresh); err != nil {
			return CompletedHistories{}, fmt.Errorf("pin managed candidate %s: %w", peer.Scope.Slot, err)
		}
		if _, err := ledger.RecordManagedPeer(ctx, peer.Scope, peer.ManifestWire, peer.ReceiptWire,
			peer.Facts, peer.ResultWire, peer.CompletedHeadWire, peer.SignProgress, peer.Refresh); err != nil {
			return CompletedHistories{}, fmt.Errorf("complete managed slot %s: %w", peer.Scope.Slot, err)
		}
	}
	seedState, err := ledger.ReadSlot(ctx, seed.Scope)
	if err != nil || seedState.Result == nil || seedState.Intent.Mode != bootstrap.IntentModeExternalSeed ||
		seedState.Head.ResultDigest == "" || seedState.SeedReceiptRecord == nil {
		return CompletedHistories{}, fmt.Errorf("seed history failed verified replay: %w", err)
	}
	completed := CompletedHistories{Seed: seedState, Peers: make(map[string]bootstrap.SlotState, 2)}
	for _, peer := range peers {
		state, err := ledger.ReadSlot(ctx, peer.Scope)
		if err != nil || state.Result == nil || state.Intent.Mode != bootstrap.IntentModeManaged ||
			state.Head.ResultDigest == "" || state.CandidateRecord == nil || state.PeerReceiptRecord == nil {
			return CompletedHistories{}, fmt.Errorf("managed slot %s failed verified replay: %w", peer.Scope.Slot, err)
		}
		completed.Peers[peer.Scope.Slot] = state
	}
	return completed, nil
}

func BuildVerifiedGuestMaterial(ctx context.Context, recipe SignedHistoryRecipe,
	completed CompletedHistories, input GuestMaterialInputs,
) (map[string][]byte, error) {
	if !recipe.Anchor.IsVerified() || len(recipe.RootPrivateKey) != ed25519.PrivateKeySize ||
		len(input.Binary) == 0 ||
		len(input.Credentials) != 3 || len(input.Configs) != 3 || len(input.VNICs) != 3 || len(input.IMDS) != 3 ||
		input.ServiceUID == 0 || input.ServiceGID == 0 {
		return nil, errors.New("guest material lacks verified anchor, binary, or three slot inputs")
	}
	rootPublic, ok := recipe.RootPrivateKey.Public().(ed25519.PublicKey)
	if !ok {
		return nil, errors.New("offline root key is not Ed25519")
	}
	rootID, err := trust.KeyID(rootPublic)
	if err != nil || len(recipe.Roots) != 1 || !bytes.Equal(recipe.Roots[rootID], rootPublic) {
		return nil, errors.New("guest trust root differs from verified offline signer")
	}
	publicDER, err := x509.MarshalPKIXPublicKey(rootPublic)
	if err != nil {
		return nil, err
	}
	rootPEM := pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: publicDER})
	if err := validateFixtureCA(input.SimulatorCA, recipe.Now); err != nil {
		return nil, err
	}
	if err := validateSimulatorTLS(input.SimulatorCA, input.SimulatorCertificate,
		input.SimulatorPrivateKey, recipe.Now); err != nil {
		return nil, err
	}
	selectionSource, err := BuildFounderSelectionSource(ctx, recipe)
	if err != nil {
		return nil, err
	}
	anchor := recipe.Anchor.Anchor()
	identityWire, err := protocol.EncodeJSON(bootstrapstart.BakedIdentity{
		SchemaVersion: 1, DeploymentID: anchor.DeploymentID, Environment: anchor.Environment, Cell: anchor.Cell,
	})
	if err != nil {
		return nil, err
	}
	material := map[string][]byte{
		"input/orchestrator":    bytes.Clone(input.Binary),
		"simulator/tls/oci.crt": bytes.Clone(input.SimulatorCertificate),
		"simulator/tls/oci.key": bytes.Clone(input.SimulatorPrivateKey),
	}
	directoryPlan := make([]GuestDirectory, 0, len(anchor.ControllerSlots)*2)
	for _, slot := range anchor.ControllerSlots {
		state := completed.Seed
		if slot != "controller-c" {
			var exists bool
			state, exists = completed.Peers[slot]
			if !exists {
				return nil, fmt.Errorf("managed controller %q has no completed history", slot)
			}
		}
		if state.Manifest == nil || state.ManifestRecord == nil || state.Result == nil ||
			state.ResultRecord == nil || state.Head.ResultDigest != state.ResultRecord.SHA256 ||
			state.Result.InstanceOCID != recipe.Observed[slot].InstanceOCID {
			return nil, fmt.Errorf("controller %q lacks exact completed ledger state", slot)
		}
		receipt := state.PeerReceiptRecord
		if slot == "controller-c" {
			receipt = state.SeedReceiptRecord
		}
		if receipt == nil {
			return nil, fmt.Errorf("controller %q lacks signed install receipt", slot)
		}
		vnic, ok := input.VNICs[slot]
		if !ok || !strings.HasPrefix(vnic.PrimaryVNICOCID, "ocid1.vnic.oc1.sa-saopaulo-1.") ||
			vnic.PrimaryPrivateIP == "" {
			return nil, fmt.Errorf("controller %q lacks GRU primary VNIC identity", slot)
		}
		networkFiles, err := productionNetworkFiles(vnic.PrimaryPrivateIP)
		if err != nil {
			return nil, fmt.Errorf("controller %q network: %w", slot, err)
		}
		imds, ok := input.IMDS[slot]
		if !ok || !strings.HasPrefix(imds.TenancyID, "ocid1.tenancy.") ||
			strings.ContainsAny(imds.TenancyID, " \r\n") ||
			len(imds.Certificate) == 0 || len(imds.PrivateKey) == 0 || len(imds.Intermediate) == 0 {
			return nil, fmt.Errorf("controller %q lacks host-only IMDS identity", slot)
		}
		imdsRoot := "simulator/imds/" + slot + "/"
		material[imdsRoot+"tenancy.txt"] = []byte(imds.TenancyID)
		material[imdsRoot+"leaf.pem"] = bytes.Clone(imds.Certificate)
		material[imdsRoot+"leaf.key"] = bytes.Clone(imds.PrivateKey)
		material[imdsRoot+"intermediate.pem"] = bytes.Clone(imds.Intermediate)
		credentials, ok := input.Credentials[slot]
		if !ok {
			return nil, fmt.Errorf("controller %q has no prepared service material", slot)
		}
		if err := validateControllerConfig(input.Configs[slot], slot, state.Result.InstanceOCID,
			vnic.PrimaryPrivateIP, input.VNICs, credentials); err != nil {
			return nil, fmt.Errorf("controller %q configuration: %w", slot, err)
		}
		materialDigests, err := expectedGuestMaterials(*state.Manifest, slot, credentials)
		if err != nil {
			return nil, err
		}
		marker := bootstrapstart.AcceptedInstall{SchemaVersion: 1,
			AnchorSHA256: recipe.Anchor.Digest(), ManifestSHA256: state.ManifestRecord.SHA256,
			ReceiptSHA256: receipt.SHA256, ImageReceiptSHA256: state.Manifest.ReleaseReceiptSHA256,
			DeploymentID: anchor.DeploymentID, Cell: string(anchor.Cell), Slot: slot,
			SeedSlot: "controller-c", ImageOCID: state.Manifest.ImageOCID,
			InstanceOCID: state.Result.InstanceOCID, PrimaryVNICOCID: vnic.PrimaryVNICOCID,
			PrimaryPrivateIP: vnic.PrimaryPrivateIP, HeadAttempt: state.Head.Attempt,
			HeadGeneration: state.Head.Generation, ResultSHA256: state.ResultRecord.SHA256,
			BinarySHA256: historyDigest(input.Binary), MaterialSHA256: materialDigests,
			AcceptedAt: recipe.Now}
		markerWire, err := protocol.EncodeJSON(marker)
		if err != nil {
			return nil, err
		}
		baked := bootstrapstart.BakedInputs{Identity: bootstrapstart.BakedIdentity{
			SchemaVersion: 1, DeploymentID: anchor.DeploymentID, Environment: anchor.Environment, Cell: anchor.Cell,
		}, Roots: recipe.Roots, AnchorWire: recipe.Anchor.Wire()}
		var artifacts []bootstrapstart.FounderFloorArtifact
		if slot == "controller-c" {
			artifacts, err = bootstrapstart.BuildVerifiedSeedFloorArtifacts(ctx, baked, marker, state,
				selectionSource, input.ServiceUID, input.ServiceGID, recipe.Now)
		} else {
			artifacts, err = bootstrapstart.BuildVerifiedPeerFloorArtifacts(ctx, baked, marker, state,
				selectionSource, input.ServiceUID, input.ServiceGID, recipe.Now)
		}
		if err != nil {
			return nil, fmt.Errorf("verify and stage %s founder floor: %w", slot, err)
		}
		floorFiles, err := checkedFloorArtifacts(artifacts, input.ServiceUID, input.ServiceGID)
		if err != nil {
			return nil, err
		}
		for _, artifact := range artifacts {
			if artifact.Directory {
				directoryPlan = append(directoryPlan, GuestDirectory{ControllerSlot: slot,
					GuestPath: artifact.Path, Mode: uint32(artifact.Mode), OwnerRole: "service:" + slot,
					UID: artifact.UID, GID: artifact.GID})
			}
		}
		directoryPlan = append(directoryPlan, GuestDirectory{ControllerSlot: slot,
			GuestPath: serviceSecretsGuestDir, Mode: 0o700, OwnerRole: "service:" + slot,
			UID: input.ServiceUID, GID: input.ServiceGID})
		root := "controllers/" + slot + "/guest-root/"
		material[root+"etc/terrascale-orchestrator/bootstrap/identity.json"] = bytes.Clone(identityWire)
		material[root+"etc/terrascale-orchestrator/controller.json"] = bytes.Clone(input.Configs[slot])
		material[root+"usr/local/share/ca-certificates/ts-fixture-oci.crt"] = bytes.Clone(input.SimulatorCA)
		for guestPath, body := range networkFiles {
			material[root+strings.TrimPrefix(guestPath, "/")] = body
		}
		material[root+"etc/terrascale-orchestrator/bootstrap/anchor.json"] = recipe.Anchor.Wire()
		material[root+"etc/terrascale-orchestrator/bootstrap/trust-roots/001.pem"] = bytes.Clone(rootPEM)
		material[root+"var/lib/terrascale-orchestrator-bootstrap/accepted-install.json"] = markerWire
		for name, body := range credentials {
			material[root+"var/lib/terrascale-orchestrator-secrets/"+name] = bytes.Clone(body)
		}
		for name, body := range floorFiles {
			material[root+name] = body
		}
	}
	directoryWire, err := protocol.EncodeJSON(directoryPlan)
	if err != nil {
		return nil, err
	}
	if _, err := parseGuestDirectories(directoryWire, materialControllers(anchor.ControllerSlots, recipe.Observed),
		func(path string) bool { _, ok := material[path]; return ok }); err != nil {
		return nil, err
	}
	material[guestDirectoryPlanPath] = directoryWire
	return material, nil
}

func syntheticSignedHistoryRecipe(t *testing.T, now time.Time, binary []byte) SignedHistoryRecipe {
	return syntheticSignedHistoryRecipeWithMaterials(t, now, binary, nil)
}

func syntheticSignedHistoryRecipeWithMaterials(t *testing.T, now time.Time, binary []byte,
	credentials map[string]map[string][]byte,
) SignedHistoryRecipe {
	return signedHistoryRecipeWithMaterialsAndReceipt(t, now, binary, credentials, nil)
}

func signedHistoryRecipeWithMaterialsAndReceipt(t *testing.T, now time.Time, binary []byte,
	credentials map[string]map[string][]byte, suppliedReceipt *release.ImageReceipt,
) SignedHistoryRecipe {
	t.Helper()
	rootPublic, rootPrivate := historyTestKey(t)
	ledgerPublic, ledgerPrivate := historyTestKey(t)
	releasePublic, releasePrivate := historyTestKey(t)
	roots, err := trust.ParseKeyring(rootPublic)
	if err != nil {
		t.Fatal(err)
	}
	slots := []string{"controller-a", "controller-b", "controller-c"}
	deploymentID := entityid.Derive("test-deployment", "production-restart-fixture")
	imageOCID := "ocid1.image.oc1.sa-saopaulo-1.restartfixture"
	if suppliedReceipt != nil {
		imageOCID = suppliedReceipt.OCIImageOCID
	}
	ledgerCapabilities := make([]trust.Capability, 0, 5)
	for _, domain := range bootstrap.BootstrapLedgerCapabilityDomains() {
		ledgerCapabilities = append(ledgerCapabilities, trust.Capability{Domain: domain,
			DeploymentID: deploymentID, Cell: "GRU", Environment: "production", Role: "controller",
			Slots: slices.Clone(slots), Actions: []string{"sign"}})
	}
	ledgerGrant := historyTestDelegation(t, rootPrivate, ledgerPublic, ledgerCapabilities, now)
	ledgerGrantWire := historyTestEnvelope(t, ledgerGrant)
	regionWire, err := trust.EncodePayload(oci.RegionIntent{SchemaVersion: 1, Generation: 1,
		BootstrapRegion: oci.RegionGRU, Regions: []oci.RegionMapping{{Cell: oci.RegionGRU, OCIRegion: "sa-saopaulo-1"}}})
	if err != nil {
		t.Fatal(err)
	}
	storage := bootstrap.StorageDomain{Namespace: "0000000000DZBJSM2QGKHTM26H", LedgerBucket: "ledger-fixture",
		LedgerKMSKeyOCID: "ocid1.key.oc1.sa-saopaulo-1.ledgerfixture", HeadBucket: "head-fixture",
		HeadKMSKeyOCID: "ocid1.key.oc1.sa-saopaulo-1.headfixture", Prefix: "private/bootstrap"}
	anchorValue := bootstrap.BootstrapAnchor{SchemaVersion: bootstrap.BootstrapAnchorSchemaVersion,
		DeploymentID: deploymentID, Environment: "production", ClusterID: "0000000000DZBJSM2QGKHTM26H",
		Cell: oci.RegionGRU, OCIRegion: "sa-saopaulo-1", StorageDomain: storage,
		ControllerSlots: slices.Clone(slots), LedgerDelegationWire: ledgerGrantWire,
		InitialRegionIntentGeneration: 1, InitialRegionIntentSHA256: historyDigest(regionWire),
		InitialRegionIntentWire: regionWire}
	anchorEnvelope, err := bootstrap.SignBootstrapAnchor(anchorValue, now.Add(-time.Minute), now.Add(2*time.Hour), rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	anchor, err := bootstrap.VerifyBootstrapAnchor(anchorEnvelope, roots, bootstrap.BootstrapAnchorExpectation{
		DeploymentID: deploymentID, Environment: "production", Cell: oci.RegionGRU,
	}, now, bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil {
		t.Fatal(err)
	}
	releaseRevision := strings.Repeat("a", 40)
	if suppliedReceipt != nil {
		releaseRevision = suppliedReceipt.SourceRevision
	}
	releaseGrant := historyTestDelegation(t, rootPrivate, releasePublic, []trust.Capability{{
		Domain: release.ImageDomain, DeploymentID: entityid.Derive("build", releaseRevision), Cell: "GRU", Environment: "production",
		Role: "oci-image", Slots: []string{imageOCID}, Actions: []string{"sign"},
	}}, now)
	releaseGrantWire := historyTestEnvelope(t, releaseGrant)
	receipt := release.ImageReceipt{Schema: release.ImageSchema, SourceRevision: releaseRevision,
		GoVersion: release.DefaultGoVersion, Architecture: "amd64", BinaryBytes: int64(len(binary)),
		BinarySHA256: historyDigest(binary), BaseImageOCID: "ocid1.image.oc1.sa-saopaulo-1.basefixture",
		QualificationSHA256: strings.Repeat("e", 64),
		BaseImageRegion:     "GRU", BaseImageSHA256: strings.Repeat("b", 64),
		KernelRelease: "6.1.0-fixture", KernelSHA256: strings.Repeat("c", 64),
		ImageFormat: "qcow2", ImageBytes: 1024, ImageSHA256: strings.Repeat("d", 64),
		OCIImageOCID: imageOCID, OCIRegion: "GRU"}
	if suppliedReceipt != nil {
		receipt = *suppliedReceipt
	}
	receiptValidity := time.Hour
	if suppliedReceipt != nil {
		// The local VM run has a 60-minute worst-case staging/boot/reboot
		// bound; two hours leaves a further hour inside the delegation cap.
		receiptValidity = 2 * time.Hour
	}
	receipt = qualifyHistoryImageFixture(t, receipt, "production", rootPrivate, now, receiptValidity)
	imageEnvelope, err := release.SignImageReceipt(receipt, "production", releaseGrant, roots,
		releasePrivate, now, receiptValidity)
	if err != nil {
		t.Fatal(err)
	}
	imageWire := historyTestEnvelope(t, imageEnvelope)
	peerGrant := historyTestDelegation(t, rootPrivate, ledgerPublic, []trust.Capability{{
		Domain: "terrascale.bootstrap.peer-receipt", DeploymentID: deploymentID, Cell: "GRU",
		Environment: "production", Role: "controller", Slots: []string{"controller-a", "controller-b"},
		Actions: []string{"sign"},
	}}, now)
	profiles := []bootstrap.LaunchProfile{
		historyTestProfile("controller-a", "FAULT-DOMAIN-1"),
		historyTestProfile("controller-b", "FAULT-DOMAIN-2"),
		historyTestProfile("controller-c", "FAULT-DOMAIN-3"),
	}
	manifestWires := make(map[string][]byte, 3)
	manifestDigests := make(map[string]string, 3)
	for _, slot := range slots {
		manifest := bootstrap.Manifest{SchemaVersion: bootstrap.ManifestSchemaVersion,
			DeploymentID: deploymentID, Environment: "production", ClusterID: anchorValue.ClusterID,
			Cell: oci.RegionGRU, OCIRegion: "sa-saopaulo-1", IntentGeneration: 1,
			IntentSHA256: anchorValue.InitialRegionIntentSHA256, ControllerRole: "controller", Slot: slot,
			SeedSlot: "controller-c", ControllerSlots: slices.Clone(slots), Profiles: slices.Clone(profiles),
			ImageOCID: imageOCID, ImageArchitecture: "linux-amd64",
			ReleaseReceiptSHA256: historyDigest(imageWire), ReleaseImageReceiptWire: imageWire,
			ReleaseDelegationWire: releaseGrantWire, PeerReceiptDelegation: &peerGrant,
			StorageDomain: storage}
		manifest.ControllerConfig = []byte(`{"nats":{},"controller":{}}`)
		manifest.ControllerConfigSHA256 = historyDigest(manifest.ControllerConfig)
		for _, name := range bootstrap.ControllerConfigFileNames {
			body := []byte(`{}`)
			manifest.ControllerFiles = append(manifest.ControllerFiles, bootstrap.ControllerConfigFile{
				Name: name, SHA256: historyDigest(body), Bytes: body,
			})
		}
		if credentials == nil {
			manifest.Secrets = []bootstrap.SecretReference{{Purpose: bootstrap.SecretRegionalShared,
				SecretOCID: "ocid1.vaultsecret.oc1.sa-saopaulo-1.regionalfixture", VersionNumber: 1,
				SHA256: historyDigest([]byte("regional fixture credential")), MaxBytes: 1024,
				TargetFile: "regional.key"}}
			if slot != "controller-c" {
				manifest.Secrets = append(manifest.Secrets, historyTestTLSSecrets(slot)...)
			}
		} else {
			material := credentials[slot]
			names := slices.Sorted(maps.Keys(material))
			for index, name := range names {
				manifest.Secrets = append(manifest.Secrets, bootstrap.SecretReference{
					Purpose: bootstrap.SecretController, Slot: slot,
					SecretOCID:    fmt.Sprintf("ocid1.vaultsecret.oc1.sa-saopaulo-1.%s-credential-%02d", slot, index),
					VersionNumber: 1, SHA256: historyDigest(material[name]),
					MaxBytes: bootstrap.MaxSecretBytes, TargetFile: name,
				})
			}
		}
		envelope, err := bootstrap.SignManifest(manifest, now.Add(-time.Minute), now.Add(2*time.Hour), rootPrivate)
		if err != nil {
			t.Fatalf("sign %s manifest: %v", slot, err)
		}
		manifestWires[slot] = historyTestEnvelope(t, envelope)
		manifestDigests[slot], err = trust.Fingerprint(envelope)
		if err != nil {
			t.Fatal(err)
		}
	}
	privateIPs := map[string]string{"controller-a": "10.44.0.11", "controller-b": "10.44.0.12", "controller-c": "10.44.0.10"}
	rows := make([]bootstrap.FounderPeerRow, 0, 2)
	for _, slot := range slots[:2] {
		profile := profiles[slices.IndexFunc(profiles, func(p bootstrap.LaunchProfile) bool { return p.Slot == slot })]
		routes := make([]bootstrap.FounderEndpoint, 0, 2)
		for _, target := range slots {
			if target != slot {
				routes = append(routes, bootstrap.FounderEndpoint{Slot: target, PrivateIP: privateIPs[target], Port: 6222})
			}
		}
		rows = append(rows, bootstrap.FounderPeerRow{Slot: slot, ManifestSHA256: manifestDigests[slot],
			ImageOCID: imageOCID, ImageCompartmentOCID: "ocid1.compartment.oc1..imagesfixture",
			CompartmentOCID: profile.CompartmentOCID, AvailabilityDomain: profile.AvailabilityDomain,
			FaultDomain: profile.FaultDomain, SubnetOCID: profile.SubnetOCID,
			NetworkSecurityGroupOCIDs: slices.Clone(profile.NetworkSecurityGroupOCIDs),
			Shape:                     profile.Shape, WholeOCPUs: 2, MemoryInGB: 12, BootVolumeGB: 50,
			BootVolumeTier: bootstrap.FounderBootVolumeTierBalanced, PrivateIP: privateIPs[slot],
			RouteEndpoints:  routes,
			ClientEndpoints: []bootstrap.FounderEndpoint{{Slot: slot, PrivateIP: privateIPs[slot], Port: 4222}},
			TLSMaterial:     historyFixtureTLSMaterial(slot, credentials)})
	}
	planValue := bootstrap.FounderPlan{SchemaVersion: bootstrap.FounderPlanSchemaVersion,
		DeploymentID: deploymentID, Cell: oci.RegionGRU, Environment: "production", SeedSlot: "controller-c",
		AnchorSHA256: anchor.Digest(), ControllerSlots: slices.Clone(slots),
		SeedManifestSHA256: manifestDigests["controller-c"], SeedPrivateIP: privateIPs["controller-c"],
		Peers: rows, Budget: bootstrap.FounderResourceBudget{WholeOCPUs: 4, MemoryInGB: 24, BootVolumeGB: 100},
		LaunchDeadline: now.Add(90 * time.Minute)}
	planPayload, err := trust.EncodePayload(planValue)
	if err != nil {
		t.Fatal(err)
	}
	planEnvelope, err := trust.Sign(planPayload, trust.Scope{Domain: bootstrap.FounderPlanDomain,
		DeploymentID: deploymentID, Cell: "GRU", Environment: "production", Role: "controller", Slot: "controller-c"},
		now, now.Add(2*time.Hour), rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	planWire := historyTestEnvelope(t, planEnvelope)
	selection := bootstrapstart.FounderSelection{SchemaVersion: 1, DeploymentID: deploymentID,
		Cell: "GRU", Environment: "production", Generation: 1,
		PlanSHA256: historyDigest(planWire), AnchorSHA256: anchor.Digest()}
	for _, slot := range slots {
		selection.Manifests = append(selection.Manifests,
			bootstrapstart.FounderManifestPin{Slot: slot, SHA256: historyDigest(manifestWires[slot])})
	}
	selectionPayload, err := trust.EncodePayload(selection)
	if err != nil {
		t.Fatal(err)
	}
	selectionEnvelope, err := trust.Sign(selectionPayload, trust.Scope{
		Domain: bootstrapstart.FounderSelectionDomain, DeploymentID: deploymentID, Cell: "GRU",
		Environment: "production", Role: "deployment-anchor", Slot: "region",
	}, now, now.Add(2*time.Hour), rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	observed := make(map[string]ObservedController, 3)
	for _, slot := range slots {
		observed[slot] = ObservedController{InstanceOCID: "ocid1.instance.oc1.sa-saopaulo-1." + slot,
			CreateKey: "create-" + slot, ProviderRequestID: "request-" + slot,
			ETag: "etag-" + slot}
		if slot != "controller-c" {
			value := observed[slot]
			value.RetryToken = "retry-" + slot
			observed[slot] = value
		}
	}
	return SignedHistoryRecipe{Anchor: anchor, FounderPlanWire: planWire,
		ManifestWires: manifestWires, FounderSelectionWire: historyTestEnvelope(t, selectionEnvelope),
		RootPrivateKey: rootPrivate, LedgerPrivateKey: ledgerPrivate, FounderPrivateKey: ledgerPrivate,
		Roots: roots, Now: now, ReviewedSeedPlanSHA256: historyDigest([]byte("reviewed seed plan")),
		Observed: observed}
}

