func (packet VerifiedPacket) Manifest() Manifest {
	manifest := packet.manifest
	manifest.Controllers = slices.Clone(manifest.Controllers)
	manifest.Files = slices.Clone(manifest.Files)
	manifest.Routes = slices.Clone(manifest.Routes)
	manifest.SourcePins = slices.Clone(manifest.SourcePins)
	return manifest
}

// Executable supplies the exact binary bytes and fixed destination consumed
// by the shipped systemd units. The driver must install these bytes at this
// path and verify the signed image receipt binds the same hash and size.
func (packet VerifiedPacket) Executable() (GuestExecutable, error) {
	if packet.root == "" {
		return GuestExecutable{}, errors.New("packet was not verified")
	}
	binary := packet.manifest.Binary
	body, err := os.ReadFile(filepath.Join(packet.root, filepath.FromSlash(binary.Path)))
	if err != nil {
		return GuestExecutable{}, err
	}
	digest := sha256.Sum256(body)
	if int64(len(body)) != binary.Size || hex.EncodeToString(digest[:]) != binary.SHA256 {
		return GuestExecutable{}, errors.New("pinned orchestrator executable changed after packet validation")
	}
	return GuestExecutable{GuestPath: binary.GuestPath, Mode: 0o755,
		Architecture: binary.Architecture, SHA256: binary.SHA256, Body: body}, nil
}

// GuestFiles returns only the entries belonging to one exact controller.
// The driver must apply each entry's owner role and mode when installing it.
func (packet VerifiedPacket) GuestFiles(slot string) ([]GuestFile, error) {
	if packet.root == "" {
		return nil, errors.New("packet was not verified")
	}
	var prefix string
	for _, controller := range packet.manifest.Controllers {
		if controller.Slot == slot {
			prefix = controller.GuestRoot + "/"
		}
	}
	if prefix == "" {
		return nil, fmt.Errorf("unknown controller slot %q", slot)
	}
	var files []GuestFile
	for _, entry := range packet.manifest.Files {
		if rest, ok := strings.CutPrefix(entry.Path, prefix); ok {
			source := filepath.Join(packet.root, filepath.FromSlash(entry.Path))
			body, err := os.ReadFile(source)
			if err != nil {
				return nil, fmt.Errorf("read guest material %q: %w", entry.Path, err)
			}
			digest := sha256.Sum256(body)
			if int64(len(body)) != entry.Size || hex.EncodeToString(digest[:]) != entry.SHA256 {
				return nil, fmt.Errorf("guest material changed after packet validation: %q", entry.Path)
			}
			files = append(files, GuestFile{SourcePath: source, GuestPath: "/" + rest, File: entry, Body: body})
		}
	}
	return files, nil
}

func (packet VerifiedPacket) SimulatorRoutes(slot string) ([]production.ReadResponse, []production.MissingRead, error) {
	if packet.root == "" {
		return nil, nil, errors.New("packet was not verified")
	}
	var instance string
	for _, controller := range packet.manifest.Controllers {
		if controller.Slot == slot {
			instance = controller.InstanceOCID
		}
	}
	if instance == "" {
		return nil, nil, fmt.Errorf("unknown simulator controller slot %q", slot)
	}
	files := make(map[string]FileEntry, len(packet.manifest.Files))
	for _, file := range packet.manifest.Files {
		files[file.Path] = file
	}
	var reads []production.ReadResponse
	var missing []production.MissingRead
	for _, route := range packet.manifest.Routes {
		if route.ControllerSlot != slot {
			continue
		}
		if route.InstanceOCID != instance {
			return nil, nil, errors.New("route instance differs from selected simulator")
		}
		if route.Status == 404 {
			missing = append(missing, production.MissingRead{Host: route.Host, RequestURI: route.RequestURI})
			continue
		}
		entry := files[route.BodyPath]
		body, err := os.ReadFile(filepath.Join(packet.root, filepath.FromSlash(route.BodyPath)))
		if err != nil {
			return nil, nil, fmt.Errorf("read simulator response %q: %w", route.BodyPath, err)
		}
		digest := sha256.Sum256(body)
		if int64(len(body)) != entry.Size || hex.EncodeToString(digest[:]) != entry.SHA256 {
			return nil, nil, fmt.Errorf("simulator response changed after packet validation: %q", route.BodyPath)
		}
		reads = append(reads, production.ReadResponse{Host: route.Host, RequestURI: route.RequestURI,
			Body: body, ContentType: "application/json", ETag: route.ETag, LastModified: route.LastModified})
	}
	return reads, missing, nil
}

// ValidatePacket rejects undeclared files and symlinks as well as digest,
// mode, ownership-role, and route inventory mismatches. It is safe to call
// before the driver copies any packet bytes into a guest image.
func ValidatePacket(root string, roots trust.Keyring, runNow time.Time) (VerifiedPacket, error) {
	if runNow.IsZero() {
		return VerifiedPacket{}, errors.New("packet validation requires a trusted run clock")
	}
	rootInfo, err := os.Lstat(root)
	if err != nil || !rootInfo.IsDir() || rootInfo.Mode()&os.ModeSymlink != 0 {
		return VerifiedPacket{}, errors.New("packet root must be a real directory")
	}
	manifestPath := filepath.Join(root, "manifest.json")
	info, err := os.Lstat(manifestPath)
	if err != nil {
		return VerifiedPacket{}, fmt.Errorf("stat packet manifest: %w", err)
	}
	if !info.Mode().IsRegular() || info.Size() > 1<<20 {
		return VerifiedPacket{}, errors.New("packet manifest must be a bounded regular file")
	}
	wire, err := os.ReadFile(manifestPath)
	if err != nil {
		return VerifiedPacket{}, fmt.Errorf("read packet manifest: %w", err)
	}
	var manifest Manifest
	if err := json.Unmarshal(wire, &manifest, json.RejectUnknownMembers(true)); err != nil {
		return VerifiedPacket{}, fmt.Errorf("decode packet manifest: %w", err)
	}
	if err := manifest.Validate(); err != nil {
		return VerifiedPacket{}, err
	}
	if runNow.Before(manifest.FixtureNow.Add(-5*time.Minute)) || runNow.After(manifest.FixtureNow.Add(5*time.Minute)) {
		return VerifiedPacket{}, errors.New("packet fixture clock differs from trusted run clock")
	}
	canonical, err := trust.EncodePayload(manifest)
	if err != nil || !bytes.Equal(canonical, wire) {
		return VerifiedPacket{}, errors.New("packet manifest is not canonical signed JSON")
	}
	sigInfo, err := os.Lstat(filepath.Join(root, "manifest.sig"))
	if err != nil || !sigInfo.Mode().IsRegular() || sigInfo.Size() > trust.MaxEnvelopeBytes {
		return VerifiedPacket{}, errors.New("packet signature must be a bounded regular file")
	}
	signature, err := os.ReadFile(filepath.Join(root, "manifest.sig"))
	if err != nil {
		return VerifiedPacket{}, fmt.Errorf("read packet signature: %w", err)
	}
	envelope, err := trust.DecodeEnvelope(signature)
	if err != nil {
		return VerifiedPacket{}, fmt.Errorf("decode packet signature: %w", err)
	}
	verified, err := trust.VerifyCurrent(envelope, manifest.scope(), roots, runNow,
		trust.Policy{MaxLifetime: 365 * 24 * time.Hour, ClockSkew: time.Minute})
	if err != nil || !bytes.Equal(verified, wire) {
		return VerifiedPacket{}, errors.New("packet manifest root signature is invalid")
	}
	listed := make(map[string]FileEntry, len(manifest.Files))
	for _, entry := range manifest.Files {
		listed[entry.Path] = entry
	}
	seen := make(map[string]bool, len(listed))
	err = filepath.WalkDir(root, func(name string, item fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		rel, err := filepath.Rel(root, name)
		if err != nil {
			return err
		}
		if rel == "." {
			return nil
		}
		rel = filepath.ToSlash(rel)
		if item.Type()&os.ModeSymlink != 0 {
			return fmt.Errorf("packet contains symlink %q", rel)
		}
		if item.IsDir() {
			return nil
		}
		if rel == "manifest.json" || rel == "manifest.sig" {
			return nil
		}
		entry, ok := listed[rel]
		if !ok || !item.Type().IsRegular() {
			return fmt.Errorf("packet contains unlisted or nonregular file %q", rel)
		}
		info, err := item.Info()
		if err != nil {
			return err
		}
		if info.Size() != entry.Size || uint32(info.Mode().Perm()) != entry.Mode {
			return fmt.Errorf("packet size or mode mismatch for %q", rel)
		}
		file, err := os.Open(name)
		if err != nil {
			return err
		}
		digest := sha256.New()
		_, copyErr := io.Copy(digest, file)
		closeErr := file.Close()
		if err := errors.Join(copyErr, closeErr); err != nil {
			return err
		}
		if hex.EncodeToString(digest.Sum(nil)) != entry.SHA256 {
			return fmt.Errorf("packet digest mismatch for %q", rel)
		}
		seen[rel] = true
		return nil
	})
	if err != nil {
		return VerifiedPacket{}, err
	}
	for _, entry := range manifest.Files {
		if !seen[entry.Path] {
			return VerifiedPacket{}, fmt.Errorf("listed packet file is absent: %q", entry.Path)
		}
	}
	return VerifiedPacket{root: root, manifest: manifest}, nil
}

func (manifest Manifest) Validate() error {
	if manifest.SchemaVersion != ManifestVersion || manifest.FixtureNow.IsZero() ||
		manifest.DeploymentID == "" || manifest.Cell != "GRU" || manifest.Environment != "production" ||
		len(manifest.Controllers) != 3 || len(manifest.SourcePins) < len(requiredSourcePaths) || len(manifest.SourcePins) > maxSourcePins ||
		len(manifest.Files) == 0 || len(manifest.Files) > 2048 || len(manifest.Routes) > 512 {
		return errors.New("invalid packet version, clock, or inventory bound")
	}
	controllers := make(map[string]string, len(manifest.Controllers))
	instances := make(map[string]struct{}, len(manifest.Controllers))
	previous := ""
	for index, controller := range manifest.Controllers {
		if controller.Slot != []string{"controller-a", "controller-b", "controller-c"}[index] {
			return fmt.Errorf("packet controller %q is outside the fixed three-slot topology", controller.Slot)
		}
		if controller.Slot <= previous || controller.Slot == "" ||
			!strings.HasPrefix(controller.InstanceOCID, "ocid1.instance.oc1.sa-saopaulo-1.") ||
			strings.ContainsAny(controller.InstanceOCID, " /?&#\r\n") ||
			len(controller.InstanceOCID) <= len("ocid1.instance.oc1.sa-saopaulo-1.") ||
			controller.GuestRoot != "controllers/"+controller.Slot+"/guest-root" {
			return fmt.Errorf("invalid, duplicated, or unsorted controller %q", controller.Slot)
		}
		if _, exists := instances[controller.InstanceOCID]; exists {
			return fmt.Errorf("multiple controllers share OCI instance %q", controller.InstanceOCID)
		}
		instances[controller.InstanceOCID] = struct{}{}
		previous = controller.Slot
		controllers[controller.Slot] = controller.InstanceOCID
	}
	files := make(map[string]FileEntry, len(manifest.Files))
	var totalBytes int64
	previous = ""
	for _, entry := range manifest.Files {
		if !canonicalPath(entry.Path) || entry.Path <= previous {
			return fmt.Errorf("packet file path is invalid, duplicated, or unsorted: %q", entry.Path)
		}
		previous = entry.Path
		role, mode := expectedOwnership(entry.Path, controllers)
		maxSize := int64(4 << 20)
		if entry.Path == "input/orchestrator" {
			maxSize = 512 << 20
		}
		if entry.Size < 0 || entry.Size > maxSize || !validDigest(entry.SHA256) ||
			entry.Mode != mode || entry.OwnerRole != role || role == "" {
			return fmt.Errorf("packet file has invalid metadata: %q", entry.Path)
		}
		totalBytes += entry.Size
		if totalBytes > maxPacketBytes {
			return errors.New("packet aggregate file bytes exceed bound")
		}
		files[entry.Path] = entry
	}
	if binaryFile, ok := files[manifest.Binary.Path]; !ok || manifest.Binary.Path != "input/orchestrator" ||
		manifest.Binary.GuestPath != "/usr/local/bin/terrascale-orchestrator" ||
		binaryFile.SHA256 != manifest.Binary.SHA256 || binaryFile.Size != manifest.Binary.Size ||
		!slices.Contains([]string{"amd64", "arm64"}, manifest.Binary.Architecture) {
		return errors.New("packet binary input does not match listed exact executable")
	}
	if _, ok := files[guestDirectoryPlanPath]; !ok {
		return errors.New("packet lacks signed guest directory plan")
	}
	for _, required := range []string{"simulator/tls/oci.crt", "simulator/tls/oci.key"} {
		if _, ok := files[required]; !ok {
			return fmt.Errorf("packet lacks signed simulator HTTPS material %q", required)
		}
	}
	for _, controller := range manifest.Controllers {
		for _, name := range []string{"tenancy.txt", "leaf.pem", "leaf.key", "intermediate.pem"} {
			if _, ok := files["simulator/imds/"+controller.Slot+"/"+name]; !ok {
				return fmt.Errorf("controller %q lacks signed IMDS %s", controller.Slot, name)
			}
		}
		prefix := controller.GuestRoot + "/etc/terrascale-orchestrator/bootstrap/"
		for _, required := range []string{"identity.json", "anchor.json", "trust-roots/001.pem"} {
			if _, ok := files[prefix+required]; !ok {
				return fmt.Errorf("controller %q lacks baked %s", controller.Slot, required)
			}
		}
		for _, required := range []string{
			"etc/terrascale-orchestrator/controller.json",
			"usr/local/share/ca-certificates/ts-fixture-oci.crt",
			"etc/systemd/network/20-terrascale-production.network",
			"etc/systemd/timesyncd.conf.d/99-terrascale-orchestrator.conf",
			"etc/hosts",
			"etc/cloud/cloud-init.disabled",
			"etc/ssh/sshd_config.d/99-terrascale-production.conf",
		} {
			if _, ok := files[controller.GuestRoot+"/"+required]; !ok {
				return fmt.Errorf("controller %q lacks production guest file %s", controller.Slot, required)
			}
		}
		for _, required := range []string{
			"var/lib/terrascale-orchestrator-bootstrap/accepted-install.json",
		} {
			if _, ok := files[controller.GuestRoot+"/"+required]; !ok {
				return fmt.Errorf("controller %q lacks restart marker %s", controller.Slot, required)
			}
		}
		credentialPrefix := controller.GuestRoot + "/var/lib/terrascale-orchestrator-secrets/"
		if _, ok := files[credentialPrefix+"operator.jwt"]; !ok {
			return fmt.Errorf("controller %q lacks signed operator credential", controller.Slot)
		}
	}
	seedRoot := "controllers/controller-c/guest-root/var/lib/terrascale-orchestrator-controller/"
	for _, required := range []string{"founder-selection-floor.json", ".founder-selection-floor.lock"} {
		if _, ok := files[seedRoot+required]; !ok {
			return fmt.Errorf("seed lacks durable founder floor %s", required)
		}
	}
	previous = ""
	for _, pin := range manifest.SourcePins {
		if !canonicalPath(pin.Path) || pin.Path <= previous || !validDigest(pin.SHA256) {
			return fmt.Errorf("packet source pin is invalid, duplicated, or unsorted: %q", pin.Path)
		}
		previous = pin.Path
	}
	for _, required := range requiredSourcePaths {
		if !slices.ContainsFunc(manifest.SourcePins, func(pin SourcePin) bool { return pin.Path == required }) {
			return fmt.Errorf("packet source pins omit required code %q", required)
		}
	}
	previous = ""
	routeBytes := make(map[string]int64, len(manifest.Controllers))
	for _, route := range manifest.Routes {
		key := route.ControllerSlot + "\n" + route.InstanceOCID + "\n" + route.Host + "\n" + route.RequestURI
		if key <= previous || controllers[route.ControllerSlot] != route.InstanceOCID || !validRoute(route, files) {
			return fmt.Errorf("packet route is invalid, duplicated, or unsorted: %q", key)
		}
		if route.Status == 200 {
			routeBytes[route.ControllerSlot] += files[route.BodyPath].Size
			if routeBytes[route.ControllerSlot] > maxRouteBodies {
				return fmt.Errorf("simulator response bytes exceed controller %q bound", route.ControllerSlot)
			}
		}
		previous = key
	}
	return nil
}

func EmitPacket(destination, sourceRoot string, manifest Manifest, material map[string][]byte,
	rootPrivateKey ed25519.PrivateKey, roots trust.Keyring, expiresAt time.Time,
) (VerifiedPacket, error) {
	if len(material) == 0 || len(material) > 2048 || manifest.FixtureNow.IsZero() ||
		!expiresAt.After(manifest.FixtureNow) || len(rootPrivateKey) != ed25519.PrivateKeySize {
		return VerifiedPacket{}, errors.New("invalid packet emission inputs")
	}
	if err := VerifySourcePins(sourceRoot, manifest.SourcePins); err != nil {
		return VerifiedPacket{}, fmt.Errorf("packet source binding: %w", err)
	}
	if _, err := os.Lstat(destination); err == nil || !errors.Is(err, os.ErrNotExist) {
		return VerifiedPacket{}, errors.New("packet destination must not exist")
	}
	controllers := make(map[string]string, len(manifest.Controllers))
	for _, controller := range manifest.Controllers {
		controllers[controller.Slot] = controller.InstanceOCID
	}
	manifest.Files = nil
	for name, body := range material {
		if !canonicalPath(name) {
			return VerifiedPacket{}, fmt.Errorf("invalid packet material path %q", name)
		}
		role, mode := expectedOwnership(name, controllers)
		if role == "" {
			return VerifiedPacket{}, fmt.Errorf("packet material path is outside allowed roots: %q", name)
		}
		if (strings.HasPrefix(name, "controllers/") || name == "input/orchestrator") && containsRootPrivateKey(body, rootPrivateKey) {
			return VerifiedPacket{}, fmt.Errorf("offline root signing key appears in guest material %q", name)
		}
		digest := sha256.Sum256(body)
		manifest.Files = append(manifest.Files, FileEntry{Path: name, SHA256: hex.EncodeToString(digest[:]),
			Size: int64(len(body)), Mode: mode, OwnerRole: role})
	}
	slices.SortFunc(manifest.Files, func(a, b FileEntry) int { return strings.Compare(a.Path, b.Path) })
	binary, ok := material["input/orchestrator"]
	if !ok {
		return VerifiedPacket{}, errors.New("packet lacks exact orchestrator binary")
	}
	binaryDigest := sha256.Sum256(binary)
	manifest.Binary.Path = "input/orchestrator"
	manifest.Binary.SHA256 = hex.EncodeToString(binaryDigest[:])
	manifest.Binary.Size = int64(len(binary))
	if err := manifest.Validate(); err != nil {
		return VerifiedPacket{}, err
	}
	wire, err := trust.EncodePayload(manifest)
	if err != nil {
		return VerifiedPacket{}, err
	}
	envelope, err := trust.Sign(wire, manifest.scope(), manifest.FixtureNow.Add(-time.Minute), expiresAt, rootPrivateKey)
	if err != nil {
		return VerifiedPacket{}, err
	}
	signature, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return VerifiedPacket{}, err
	}
	parent := filepath.Dir(destination)
	if err := os.MkdirAll(parent, 0o700); err != nil {
		return VerifiedPacket{}, err
	}
	staging, err := os.MkdirTemp(parent, ".production-packet-")
	if err != nil {
		return VerifiedPacket{}, err
	}
	defer os.RemoveAll(staging)
	for _, entry := range manifest.Files {
		name := filepath.Join(staging, filepath.FromSlash(entry.Path))
		if err := os.MkdirAll(filepath.Dir(name), 0o700); err != nil {
			return VerifiedPacket{}, err
		}
		if err := os.WriteFile(name, material[entry.Path], os.FileMode(entry.Mode)); err != nil {
			return VerifiedPacket{}, err
		}
	}
	if err := os.WriteFile(filepath.Join(staging, "manifest.json"), wire, 0o600); err != nil {
		return VerifiedPacket{}, err
	}
	if err := os.WriteFile(filepath.Join(staging, "manifest.sig"), signature, 0o600); err != nil {
		return VerifiedPacket{}, err
	}
	if _, err := ValidatePacket(staging, roots, time.Now().UTC()); err != nil {
		return VerifiedPacket{}, fmt.Errorf("emitted packet failed self-verification: %w", err)
	}
	if err := unix.Renameat2(unix.AT_FDCWD, staging, unix.AT_FDCWD, destination, unix.RENAME_NOREPLACE); err != nil {
		return VerifiedPacket{}, err
	}
	return ValidatePacket(destination, roots, time.Now().UTC())
}

func RequiredSourcePaths() []string {
	paths := slices.Clone(requiredSourcePaths)
	slices.Sort(paths)
	return paths
}

// VerifySourcePins binds a packet recipe to the exact local source files used
// by its signing, ledger, admission, and simulator APIs before emission.
func VerifySourcePins(sourceRoot string, pins []SourcePin) error {
	if len(pins) < len(requiredSourcePaths) || len(pins) > maxSourcePins {
		return errors.New("source pin inventory is absent or oversized")
	}
	for _, required := range requiredSourcePaths {
		if !slices.ContainsFunc(pins, func(pin SourcePin) bool { return pin.Path == required }) {
			return fmt.Errorf("source pins omit required code %q", required)
		}
	}
	root, err := filepath.Abs(sourceRoot)
	if err != nil {
		return err
	}
	rootInfo, err := os.Lstat(root)
	if err != nil || !rootInfo.IsDir() || rootInfo.Mode()&os.ModeSymlink != 0 {
		return errors.New("source root must be a real directory")
	}
	resolved, err := filepath.EvalSymlinks(root)
	if err != nil || resolved != root {
		return errors.New("source root has a symlink ancestor")
	}
	previous := ""
	for _, pin := range pins {
		if !canonicalPath(pin.Path) || pin.Path <= previous || !validDigest(pin.SHA256) {
			return fmt.Errorf("invalid source pin %q", pin.Path)
		}
		previous = pin.Path
		name := filepath.Join(root, filepath.FromSlash(pin.Path))
		parent := filepath.Dir(name)
		for parent != root {
			info, err := os.Lstat(parent)
			if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
				return fmt.Errorf("source pin has non-directory or symlink ancestor: %q", pin.Path)
			}
			parent = filepath.Dir(parent)
		}
		info, err := os.Lstat(name)
		if err != nil || !info.Mode().IsRegular() {
			return fmt.Errorf("source pin is missing or nonregular: %q", pin.Path)
		}
		file, err := os.Open(name)
		if err != nil {
			return err
		}
		digest := sha256.New()
		_, copyErr := io.Copy(digest, file)
		closeErr := file.Close()
		if err := errors.Join(copyErr, closeErr); err != nil {
			return err
		}
		if hex.EncodeToString(digest.Sum(nil)) != pin.SHA256 {
			return fmt.Errorf("source pin digest mismatch: %q", pin.Path)
		}
	}
	return nil
}

var completedRecipeSourceDirs = []string{
	"cmd/terrascale-orchestrator",
	"deploy/image",
	"deploy/systemd",
	"internal/app",
	"internal/bootstrap",
	"internal/bootstrapstart",
	"internal/cli",
	"internal/commandio",
	"internal/release",
	"internal/trust",
	"tests/firecracker/production",
}

// CurrentCompletedSourcePins computes a sorted SHA-256 inventory from the
// current source tree. The packet writer verifies these pins again before
// publication, so a source edit between preparation and emission fails closed.
func CurrentCompletedSourcePins(sourceRoot string) ([]SourcePin, error) {
	root, err := completedSourceRoot(sourceRoot)
	if err != nil {
		return nil, err
	}
	paths, err := completedSourcePaths(root)
	if err != nil {
		return nil, err
	}
	pins := make([]SourcePin, 0, len(paths))
	for _, path := range paths {
		name := filepath.Join(root, filepath.FromSlash(path))
		file, err := os.Open(name)
		if err != nil {
			return nil, err
		}
		digest := sha256.New()
		_, copyErr := io.Copy(digest, file)
		closeErr := file.Close()
		if err := errors.Join(copyErr, closeErr); err != nil {
			return nil, err
		}
		pins = append(pins, SourcePin{Path: path, SHA256: hex.EncodeToString(digest.Sum(nil))})
	}
	if err := VerifyCompletedSourcePins(root, pins); err != nil {
		return nil, err
	}
	return pins, nil
}

// VerifyCompletedSourcePins checks both hashes and full directory coverage.
// Unlike a fixed required-path list, it rejects a recipe that omits a newly
// added production source file from one of the completed recipe packages.
func VerifyCompletedSourcePins(sourceRoot string, pins []SourcePin) error {
	root, err := completedSourceRoot(sourceRoot)
	if err != nil {
		return err
	}
	paths, err := completedSourcePaths(root)
	if err != nil {
		return err
	}
	for _, path := range paths {
		if !slices.ContainsFunc(pins, func(pin SourcePin) bool { return pin.Path == path }) {
			return fmt.Errorf("completed source pins omit %q", path)
		}
	}
	return VerifySourcePins(root, pins)
}

func completedSourceRoot(sourceRoot string) (string, error) {
	root, err := filepath.Abs(sourceRoot)
	if err != nil {
		return "", err
	}
	info, err := os.Lstat(root)
	if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
		return "", errors.New("source root must be a real directory")
	}
	resolved, err := filepath.EvalSymlinks(root)
	if err != nil || resolved != root {
		return "", errors.New("source root has a symlink ancestor")
	}
	return root, nil
}

func completedSourcePaths(root string) ([]string, error) {
	var paths []string
	for _, directory := range completedRecipeSourceDirs {
		if !canonicalPath(directory) {
			return nil, fmt.Errorf("invalid completed source directory %q", directory)
		}
		if err := filepath.WalkDir(filepath.Join(root, filepath.FromSlash(directory)),
			func(name string, item fs.DirEntry, walkErr error) error {
				if walkErr != nil {
					return walkErr
				}
				if item.Type()&os.ModeSymlink != 0 {
					return fmt.Errorf("completed source tree contains symlink %q", name)
				}
				if item.IsDir() {
					return nil
				}
				if !item.Type().IsRegular() {
					return fmt.Errorf("completed source tree contains nonregular file %q", name)
				}
				if !strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, ".service") &&
					!strings.HasSuffix(name, ".sh") && !strings.HasSuffix(name, ".sysusers") &&
					!strings.HasSuffix(name, ".py") || strings.HasSuffix(name, "_test.go") ||
					strings.HasPrefix(filepath.Base(name), "test_") {
					return nil
				}
				relative, err := filepath.Rel(root, name)
				if err != nil {
					return err
				}
				path := filepath.ToSlash(relative)
				if !canonicalPath(path) {
					return fmt.Errorf("invalid completed source path %q", path)
				}
				paths = append(paths, path)
				return nil
			}); err != nil {
			return nil, err
		}
	}
	slices.Sort(paths)
	paths = slices.Compact(paths)
	if len(paths) > maxSourcePins {
		return nil, errors.New("completed source inventory exceeds packet pin bound")
	}
	for _, required := range requiredSourcePaths {
		if !slices.Contains(paths, required) {
			return nil, fmt.Errorf("completed source inventory omits baseline %q", required)
		}
	}
	return paths, nil
}

func (packet VerifiedPacket) GuestDirectories(slot string) ([]GuestDirectory, error) {
	if packet.root == "" {
		return nil, errors.New("packet was not verified")
	}
	var listed *FileEntry
	files := make(map[string]bool, len(packet.manifest.Files))
	for index := range packet.manifest.Files {
		entry := &packet.manifest.Files[index]
		files[entry.Path] = true
		if entry.Path == guestDirectoryPlanPath {
			listed = entry
		}
	}
	if listed == nil {
		return nil, errors.New("packet lacks signed guest directory plan")
	}
	name := filepath.Join(packet.root, guestDirectoryPlanPath)
	info, err := os.Lstat(name)
	if err != nil || !info.Mode().IsRegular() || info.Size() != listed.Size {
		return nil, errors.New("signed guest directory plan is missing or nonregular")
	}
	wire, err := os.ReadFile(name)
	if err != nil {
		return nil, err
	}
	digest := sha256.Sum256(wire)
	if hex.EncodeToString(digest[:]) != listed.SHA256 {
		return nil, errors.New("signed guest directory plan changed")
	}
	plan, err := parseGuestDirectories(wire, packet.manifest.Controllers,
		func(path string) bool { return files[path] })
	if err != nil {
		return nil, err
	}
	var selected []GuestDirectory
	for _, directory := range plan {
		if directory.ControllerSlot == slot {
			selected = append(selected, directory)
		}
	}
	if len(selected) != 2 {
		return nil, fmt.Errorf("unknown or incomplete controller slot %q", slot)
	}
	return selected, nil
}

func (packet VerifiedPacket) SimulatorConfig(slot string) (production.Config, error) {
	var instance string
	for _, controller := range packet.manifest.Controllers {
		if controller.Slot == slot {
			instance = controller.InstanceOCID
		}
	}
	if instance == "" {
		return production.Config{}, fmt.Errorf("unknown simulator slot %q", slot)
	}
	root := "simulator/imds/" + slot + "/"
	tenancy, err := packet.readListedFile(root + "tenancy.txt")
	if err != nil {
		return production.Config{}, err
	}
	certificate, err := packet.readListedFile(root + "leaf.pem")
	if err != nil {
		return production.Config{}, err
	}
	key, err := packet.readListedFile(root + "leaf.key")
	if err != nil {
		return production.Config{}, err
	}
	intermediate, err := packet.readListedFile(root + "intermediate.pem")
	if err != nil {
		return production.Config{}, err
	}
	reads, missing, err := packet.SimulatorRoutes(slot)
	if err != nil {
		return production.Config{}, err
	}
	address, err := packet.PrivateAddress(slot)
	if err != nil {
		return production.Config{}, err
	}
	config := production.Config{Region: "sa-saopaulo-1", InstanceID: instance,
		DescriptorSlot: slot, PrimaryPrivateIP: address, TenancyID: string(tenancy), LeafCertificate: certificate,
		LeafPrivateKey: key, Intermediate: intermediate, Reads: reads, Missing: missing}
	if _, err := production.NewSimulator(config); err != nil {
		return production.Config{}, fmt.Errorf("validate %s simulator: %w", slot, err)
	}
	return config, nil
}

// PrivateAddress returns the signed completed-install VNIC address for one VM.
func (packet VerifiedPacket) PrivateAddress(slot string) (string, error) {
	files, err := packet.GuestFiles(slot)
	if err != nil {
		return "", err
	}
	for _, file := range files {
		if file.GuestPath != "/var/lib/terrascale-orchestrator-bootstrap/accepted-install.json" {
			continue
		}
		var marker bootstrapstart.AcceptedInstall
		if err := protocol.DecodeStrict(file.Body, &marker, 1<<20); err != nil ||
			marker.Slot != slot || marker.PrimaryPrivateIP == "" {
			return "", fmt.Errorf("controller %q has invalid signed restart marker", slot)
		}
		return marker.PrimaryPrivateIP, nil
	}
	return "", fmt.Errorf("controller %q lacks signed restart marker", slot)

func (packet VerifiedPacket) SimulatorTLS(now time.Time) ([]byte, []byte, error) {
	certificate, err := packet.readListedFile("simulator/tls/oci.crt")
	if err != nil {
		return nil, nil, err
	}
	key, err := packet.readListedFile("simulator/tls/oci.key")
	if err != nil {
		return nil, nil, err
	}
	var ca []byte
	for _, controller := range packet.manifest.Controllers {
		files, err := packet.GuestFiles(controller.Slot)
		if err != nil {
			return nil, nil, err
		}
		found := false
		for _, file := range files {
			if file.GuestPath != fixtureCAGuestPath {
				continue
			}
			if found || ca != nil && !bytes.Equal(ca, file.Body) {
				return nil, nil, errors.New("guest OCI trust anchors differ across controllers")
			}
			ca = file.Body
			found = true
		}
		if !found {
			return nil, nil, fmt.Errorf("controller %q lacks guest OCI trust anchor", controller.Slot)
		}
	}
	if err := validateSimulatorTLS(ca, certificate, key, now); err != nil {
		return nil, nil, err
	}
	return certificate, key, nil
}

// ValidateProductionGuests closes the packet's config, credential, marker,
// VNIC, CA and HTTPS-server boundary before an image is touched.
func (packet VerifiedPacket) ValidateProductionGuests(now time.Time) error {
	if _, _, err := packet.SimulatorTLS(now); err != nil {
		return err
	}
	observations := make(map[string]GuestObservation, len(packet.manifest.Controllers))
	configs := make(map[string][]byte, len(packet.manifest.Controllers))
	credentials := make(map[string]map[string][]byte, len(packet.manifest.Controllers))
	network := make(map[string]map[string][]byte, len(packet.manifest.Controllers))
