type packetSimulatorDispatcher struct {
	t       *testing.T
	server  *httptest.Server
	client  *http.Client
	allowed map[string][]byte
}

func newPacketSimulatorDispatcher(t *testing.T, config production.Config) (*production.Simulator, packetSimulatorDispatcher) {
	t.Helper()
	simulator, err := production.NewSimulator(config)
	if err != nil {
		t.Fatalf("simulator rejected packet routes: %v", err)
	}
	server := httptest.NewServer(simulator)
	t.Cleanup(server.Close)
	transport := &http.Transport{Proxy: nil}
	t.Cleanup(transport.CloseIdleConnections)
	client := &http.Client{Transport: transport, Timeout: 10 * time.Second,
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	allowed := map[string][]byte{"POST\nauth.sa-saopaulo-1.oraclecloud.com\n/v1/x509": nil}
	for _, path := range []string{"/opc/v2/instance/id", "/opc/v2/instance/metadata/terrascale-bootstrap",
		"/opc/v2/instance/region", "/opc/v2/identity/cert.pem", "/opc/v2/identity/key.pem",
		"/opc/v2/identity/intermediate.pem", "/opc/v2/vnics/"} {
		allowed["GET\n169.254.169.254\n"+path] = nil
	}
	for _, read := range config.Reads {
		allowed["GET\n"+read.Host+"\n"+read.RequestURI] = bytes.Clone(read.Body)
	}
	return simulator, packetSimulatorDispatcher{t: t, server: server, client: client, allowed: allowed}
}

func (dispatcher packetSimulatorDispatcher) Do(request *http.Request) (*http.Response, error) {
	request = request.Clone(request.Context())
	if request.Host == "" {
		request.Host = request.URL.Host
	}
	key := request.Method + "\n" + request.Host + "\n" + request.URL.RequestURI()
	expected, allowed := dispatcher.allowed[key]
	if !allowed || request.Host != request.URL.Host {
		return nil, fmt.Errorf("SDK request is outside exact packet routes")
	}
	request.URL.Scheme = "http"
	request.URL.Host = strings.TrimPrefix(dispatcher.server.URL, "http://")
	request.RequestURI = ""
	response, err := dispatcher.client.Do(request)
	if err != nil || expected == nil {
		return response, err
	}
	body, readErr := io.ReadAll(io.LimitReader(response.Body, int64(len(expected))+1))
	closeErr := response.Body.Close()
	if readErr != nil || closeErr != nil || response.StatusCode != http.StatusOK || !bytes.Equal(body, expected) {
		return nil, fmt.Errorf("SDK socket response differs from packet provider bytes: status=%d read=%v close=%v", response.StatusCode, readErr, closeErr)
	}
	dispatcher.t.Logf("SDK socket response route_sha256=%x body_sha256=%x", sha256.Sum256([]byte(key)), sha256.Sum256(body))
	response.Body = io.NopCloser(bytes.NewReader(body))
	return response, nil
}

// assertPacketComputeSDK exercises the signed packet's exact routes through
// the real instance-principal SDK. The fixturetest build also repeats these
// reads through the production instance observer.
func assertPacketComputeSDK(t *testing.T, packet VerifiedPacket, slot string,
	observed ObservedController, vnic GuestObservation,
) {
	t.Helper()
	config, err := packet.SimulatorConfig(slot)
	if err != nil {
		t.Fatal(err)
	}
	if config.PrimaryPrivateIP != vnic.PrimaryPrivateIP {
		t.Fatalf("%s simulator VNIC address = %q, want %q", slot, config.PrimaryPrivateIP, vnic.PrimaryPrivateIP)
	}
	simulator, dispatcher := newPacketSimulatorDispatcher(t, config)
	defer dispatcher.server.Close()
	provider, err := auth.InstancePrincipalConfigurationForRegionWithCustomClient(
		common.Region("sa-saopaulo-1"),
		func(common.HTTPRequestDispatcher) (common.HTTPRequestDispatcher, error) { return dispatcher, nil })
	if err != nil {
		t.Fatalf("%s instance principal configuration: %v", slot, err)
	}
	if _, err := provider.KeyID(); err != nil {
		t.Fatalf("%s instance principal federation: %v; requests=%#v", slot, err, simulator.Requests())
	}
	compute, err := core.NewComputeClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	compute.HTTPClient = dispatcher
	network, err := core.NewVirtualNetworkClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	network.HTTPClient = dispatcher
	instance, err := compute.GetInstance(t.Context(), core.GetInstanceRequest{InstanceId: new(observed.InstanceOCID)})
	if err != nil || instance.Id == nil || *instance.Id != observed.InstanceOCID ||
		instance.Etag == nil || *instance.Etag != observed.ETag ||
		instance.CompartmentId == nil || instance.ImageId == nil ||
		instance.AvailabilityDomain == nil || instance.FaultDomain == nil || instance.Shape == nil ||
		instance.LifecycleState != core.InstanceLifecycleStateRunning {
		t.Fatalf("%s SDK GetInstance decoded unexpected response: %+v, %v", slot, instance, err)
	}
	attachments, err := compute.ListVnicAttachments(t.Context(), core.ListVnicAttachmentsRequest{
		CompartmentId: instance.CompartmentId, InstanceId: new(observed.InstanceOCID), Limit: new(50),
	})
	if err != nil || len(attachments.Items) != 1 ||
		attachments.Items[0].VnicId == nil || *attachments.Items[0].VnicId != vnic.PrimaryVNICOCID ||
		attachments.Items[0].LifecycleState != core.VnicAttachmentLifecycleStateAttached {
		t.Fatalf("%s SDK ListVnicAttachments decoded unexpected response: %+v, %v", slot, attachments, err)
	}
	primary, err := network.GetVnic(t.Context(), core.GetVnicRequest{VnicId: new(vnic.PrimaryVNICOCID)})
	if err != nil || primary.Id == nil || *primary.Id != vnic.PrimaryVNICOCID ||
		primary.PrivateIp == nil || *primary.PrivateIp != vnic.PrimaryPrivateIP ||
		primary.SubnetId == nil || primary.CompartmentId == nil || primary.AvailabilityDomain == nil ||
		*primary.CompartmentId != vnic.NetworkCompartmentOCID ||
		primary.IsPrimary == nil || !*primary.IsPrimary ||
		primary.LifecycleState != core.VnicLifecycleStateAvailable {
		t.Fatalf("%s SDK GetVnic decoded unexpected response: %+v, %v", slot, primary, err)
	}
	subnet, err := network.GetSubnet(t.Context(), core.GetSubnetRequest{SubnetId: primary.SubnetId})
	if err != nil || subnet.Id == nil || *subnet.Id != *primary.SubnetId ||
		subnet.CompartmentId == nil || *subnet.CompartmentId != vnic.NetworkCompartmentOCID ||
		*subnet.CompartmentId == *instance.CompartmentId ||
		subnet.VcnId == nil || *subnet.VcnId != vnic.VCNOCID ||
		subnet.AvailabilityDomain == nil || *subnet.AvailabilityDomain != *primary.AvailabilityDomain ||
		subnet.LifecycleState != core.SubnetLifecycleStateAvailable {
		t.Fatalf("%s SDK GetSubnet decoded unexpected network identity: %+v, %v", slot, subnet, err)
	}
	additionalComputeReads := assertPacketComputeObserver(t, provider, &compute, &network,
		observed, vnic, instance, primary, config)
	computeReads := 0
	for _, request := range simulator.Requests() {
		if !request.Listed || request.Status != http.StatusOK {
			t.Fatalf("%s SDK used an unlisted or failed route: %+v", slot, request)
		}
		if request.Host == "iaas.sa-saopaulo-1.oraclecloud.com" {
			computeReads++
		}
	}
	if computeReads != 4+additionalComputeReads || simulator.OverflowCount() != 0 {
		t.Fatalf("%s SDK Compute request count = %d, audit overflow = %d", slot,
			computeReads, simulator.OverflowCount())
	}
}

func NewSimulator(config Config) (*Simulator, error) {
	if config.Region != "sa-saopaulo-1" || config.InstanceID == "" || config.DescriptorSlot == "" ||
		!strings.HasPrefix(config.TenancyID, "ocid1.tenancy.") {
		return nil, errors.New("simulator requires the pinned GRU fixture identity")
	}
	if address, err := netip.ParseAddr(config.PrimaryPrivateIP); err != nil || !address.Is4() ||
		!address.IsPrivate() || address.String() != config.PrimaryPrivateIP {
		return nil, errors.New("simulator requires the slot's primary private IPv4 address")
	}
	config.LeafCertificate = bytes.Clone(config.LeafCertificate)
	config.LeafPrivateKey = bytes.Clone(config.LeafPrivateKey)
	config.Intermediate = bytes.Clone(config.Intermediate)
	if len(config.LeafCertificate) > maxRequest || len(config.LeafPrivateKey) > maxRequest ||
		len(config.Intermediate) > maxRequest || len(config.Reads)+len(config.Missing) > maxRoutes {
		return nil, errors.New("simulator fixture exceeds material or route bounds")
	}
	block, rest := pem.Decode(config.LeafCertificate)
	if block == nil || block.Type != "CERTIFICATE" || len(bytes.TrimSpace(rest)) != 0 {
		return nil, errors.New("invalid leaf certificate PEM")
	}
	leaf, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("parse leaf certificate: %w", err)
	}
	privateBlock, rest := pem.Decode(config.LeafPrivateKey)
	if privateBlock == nil || len(bytes.TrimSpace(rest)) != 0 {
		return nil, errors.New("invalid leaf private key PEM")
	}
	var key *rsa.PrivateKey
	switch privateBlock.Type {
	case "RSA PRIVATE KEY":
		key, err = x509.ParsePKCS1PrivateKey(privateBlock.Bytes)
	case "PRIVATE KEY":
		var parsed any
		parsed, err = x509.ParsePKCS8PrivateKey(privateBlock.Bytes)
		key, _ = parsed.(*rsa.PrivateKey)
	default:
		return nil, errors.New("leaf private key must be RSA")
	}
	public, ok := leaf.PublicKey.(*rsa.PublicKey)
	if err != nil || key == nil || !ok || !public.Equal(&key.PublicKey) {
		return nil, errors.New("leaf certificate and RSA key do not match")
	}
	foundTenancy := false
	for _, name := range leaf.Subject.Names {
		if value, ok := name.Value.(string); ok && value == "opc-tenant:"+config.TenancyID {
			foundTenancy = true
		}
	}
	if !foundTenancy {
		return nil, errors.New("leaf certificate does not bind the fixture tenancy")
	}
	intermediate, extra := pem.Decode(config.Intermediate)
	if intermediate == nil || intermediate.Type != "CERTIFICATE" || len(bytes.TrimSpace(extra)) != 0 {
		return nil, errors.New("invalid intermediate certificate PEM")
	}
	issuer, err := x509.ParseCertificate(intermediate.Bytes)
	if err != nil {
		return nil, fmt.Errorf("parse intermediate certificate: %w", err)
	}
	if err := leaf.CheckSignatureFrom(issuer); err != nil {
		return nil, fmt.Errorf("leaf certificate is not signed by fixture intermediate: %w", err)
	}
	tokenKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return nil, fmt.Errorf("create host-only federation token key: %w", err)
	}
	simulator := &Simulator{
		config: config, leaf: leaf, leafKey: key, tokenKey: tokenKey,
		authHost:    "auth.sa-saopaulo-1.oraclecloud.com",
		computeHost: "iaas.sa-saopaulo-1.oraclecloud.com",
		storageHost: "objectstorage.sa-saopaulo-1.oraclecloud.com",
		reads:       make(map[routeKey]ReadResponse), missing: make(map[routeKey]struct{}),
		sessions: make(map[string]session), now: time.Now,
	}
	for _, response := range config.Reads {
		if err := simulator.addRead(response); err != nil {
			return nil, err
		}
	}
	for _, missing := range config.Missing {
		if err := simulator.addMissing(missing); err != nil {
			return nil, err
		}
	}
	return simulator, nil
}

func (simulator *Simulator) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	record := simulator.auditRecord(request)
	simulator.mu.Lock()
	if len(simulator.requests) >= maxRecordedRequests {
		if simulator.overflow < ^uint64(0) {
			simulator.overflow++
		}
		simulator.mu.Unlock()
		reject(writer, http.StatusTooManyRequests)
		return
	}
	index := len(simulator.requests)
	simulator.requests = append(simulator.requests, record)
	simulator.mu.Unlock()
	status := simulator.serve(writer, request)
	simulator.mu.Lock()
	simulator.requests[index].Status = status
	simulator.mu.Unlock()
}

func (simulator *Simulator) auditRecord(request *http.Request) RequestRecord {
	uri := request.URL.RequestURI()
	key := routeKey{request.Host, uri}
	_, found := simulator.reads[key]
	_, missing := simulator.missing[key]
	listed := request.Method == http.MethodGet && (found || missing ||
		request.Host == imdsHost && slices.Contains(imdsPaths, uri)) || request.Method == http.MethodPost && request.Host == simulator.authHost && uri == "/v1/x509"
	digest := sha256.Sum256([]byte(request.Method + "\n" + request.Host + "\n" + uri))
	method := request.Method
	host := request.Host
	if listed {
		uri = request.URL.EscapedPath()
		if request.URL.RawQuery != "" {
			uri += "?[redacted]"
		}
	} else {
		uri = "[unlisted]"
		if !slices.Contains([]string{imdsHost, simulator.authHost, simulator.computeHost, simulator.storageHost}, host) {
			host = "[unlisted]"
		}
		if !slices.Contains([]string{http.MethodGet, http.MethodPost, http.MethodPut, http.MethodPatch, http.MethodDelete}, method) {
			method = "[unlisted]"
		}
	}
	return RequestRecord{
		Method: boundAuditText(method, 16), Host: boundAuditText(host, 255),
		RequestURI: boundAuditText(uri, 4096), RouteSHA256: hex.EncodeToString(digest[:]), Listed: listed,
	}
}

func boundAuditText(value string, maximum int) string {
	if len(value) > maximum {
		return value[:maximum] + "[truncated]"
	}
	return value
}

func (simulator *Simulator) serve(writer http.ResponseWriter, request *http.Request) int {
	if request.Host == imdsHost && request.Method == http.MethodGet && request.ContentLength == 0 {
		if request.Header.Get("Authorization") != "Bearer Oracle" {
			return reject(writer, http.StatusForbidden)
		}
		var body []byte
		switch request.URL.RequestURI() {
		case "/opc/v2/instance/id":
			body = []byte(simulator.config.InstanceID)
		case "/opc/v2/instance/metadata/terrascale-bootstrap":
			body = []byte(fmt.Sprintf(`{"schemaVersion":1,"slot":%q}`, simulator.config.DescriptorSlot))
		case "/opc/v2/instance/region":
			body = []byte(simulator.config.Region)
		case "/opc/v2/identity/cert.pem":
			body = simulator.config.LeafCertificate
		case "/opc/v2/identity/key.pem":
			body = simulator.config.LeafPrivateKey
		case "/opc/v2/identity/intermediate.pem":
			body = simulator.config.Intermediate
		case "/opc/v2/vnics/":
			// OCI lists the primary VNIC first; NetBird enrollment reads only
			// its privateIp.
			body = []byte(fmt.Sprintf(`[{"privateIp":%q}]`, simulator.config.PrimaryPrivateIP))
		default:
			return reject(writer, http.StatusMisdirectedRequest)
		}
		writer.WriteHeader(http.StatusOK)
		_, _ = writer.Write(body)
		return http.StatusOK
	}
	if request.Host == simulator.authHost && request.URL.RequestURI() == "/v1/x509" && request.Method == http.MethodPost {
		return simulator.federate(writer, request)
	}
	if request.Method != http.MethodGet {
		return reject(writer, http.StatusMethodNotAllowed)
	}
	if request.ContentLength != 0 {
		return reject(writer, http.StatusBadRequest)
	}
	if err := simulator.verifyService(request); err != nil {
		return reject(writer, http.StatusForbidden)
	}
	key := routeKey{request.Host, request.URL.RequestURI()}
	if _, missing := simulator.missing[key]; missing {
		writer.Header().Set("Content-Type", "application/json")
		writer.Header().Set("Date", simulator.now().UTC().Format(http.TimeFormat))
		return reject(writer, http.StatusNotFound)
	}
	response, exists := simulator.reads[key]
	if !exists {
		return reject(writer, http.StatusMisdirectedRequest)
	}
	writer.Header().Set("Content-Type", response.ContentType)
	writer.Header().Set("ETag", response.ETag)
	writer.Header().Set("Last-Modified", response.LastModified.UTC().Format(http.TimeFormat))
	writer.Header().Set("Date", simulator.now().UTC().Format(http.TimeFormat))
	writer.Header().Set("Content-Length", fmt.Sprint(len(response.Body)))
	writer.WriteHeader(http.StatusOK)
	_, _ = writer.Write(response.Body)
	return http.StatusOK
}

func (simulator *Simulator) federate(writer http.ResponseWriter, request *http.Request) int {
	if request.ContentLength < 1 || request.ContentLength > maxRequest {
		return reject(writer, http.StatusBadRequest)
	}
	body, err := io.ReadAll(io.LimitReader(request.Body, maxRequest+1))
	if err != nil || len(body) != int(request.ContentLength) || len(body) > maxRequest {
		return reject(writer, http.StatusBadRequest)
	}
	var submitted federationRequest
	if err := json.Unmarshal(body, &submitted); err != nil || submitted.FingerprintAlgorithm != "SHA256" ||
		len(submitted.IntermediateCertificates) != 1 ||
		submitted.Certificate != encodedPEM(simulator.config.LeafCertificate) ||
		submitted.IntermediateCertificates[0] != encodedPEM(simulator.config.Intermediate) {
		return reject(writer, http.StatusForbidden)
	}
	publicDER, err := base64.StdEncoding.DecodeString(submitted.PublicKey)
	if err != nil {
		return reject(writer, http.StatusForbidden)
	}
	parsed, err := x509.ParsePKIXPublicKey(publicDER)
	public, ok := parsed.(*rsa.PublicKey)
	if err != nil || !ok || public.N.BitLen() < 2048 {
		return reject(writer, http.StatusForbidden)
	}
	fingerprint := sha256.Sum256(simulator.leaf.Raw)
	parts := make([]string, len(fingerprint))
	for index, value := range fingerprint {
		parts[index] = hex.EncodeToString([]byte{value})
	}
	keyID := simulator.config.TenancyID + "/fed-x509-sha256/" + strings.Join(parts, ":")
	if err := verifySignature(request, body, &simulator.leafKey.PublicKey, keyID,
		"date (request-target) content-length content-type x-content-sha256", false, simulator.now()); err != nil {
		return reject(writer, http.StatusForbidden)
	}
	expires := simulator.now().Add(tokenLifetime)
	simulator.mu.Lock()
	for prior, entry := range simulator.sessions {
		if !simulator.now().Before(entry.expires) {
			delete(simulator.sessions, prior)
		}
	}
	if len(simulator.sessions) >= maxSessions {
		simulator.mu.Unlock()
		return reject(writer, http.StatusTooManyRequests)
	}
	token, err := simulator.newToken(expires)
	if err != nil {
		simulator.mu.Unlock()
		return reject(writer, http.StatusInternalServerError)
	}
	simulator.sessions[token] = session{public: public, expires: expires}
	simulator.mu.Unlock()
	response, err := json.Marshal(struct {
		Token string `json:"token"`
	}{Token: token})
	if err != nil {
		return reject(writer, http.StatusInternalServerError)
	}
	writer.Header().Set("Content-Type", "application/json")
	writer.WriteHeader(http.StatusOK)
	_, _ = writer.Write(response)
	return http.StatusOK
}

func encodedPEM(wire []byte) string {
	block, _ := pem.Decode(wire)
	if block == nil {
		return ""
	}
	return base64.StdEncoding.EncodeToString(block.Bytes)
}

func (simulator *Simulator) newToken(expires time.Time) (string, error) {
	header := base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"RS256","typ":"JWT"}`))
	nonce := make([]byte, 16)
	if _, err := rand.Read(nonce); err != nil {
		return "", err
	}
	payload, err := json.Marshal(struct {
		Expires  int64  `json:"exp"`
		Subject  string `json:"sub"`
		Instance string `json:"opc-instance"`
		Type     string `json:"ptype"`
		Tenancy  string `json:"tenant"`
		ID       string `json:"jti"`
	}{Expires: expires.Unix(), Subject: simulator.config.InstanceID,
		Instance: simulator.config.InstanceID, Type: "instance", Tenancy: simulator.config.TenancyID,
		ID: base64.RawURLEncoding.EncodeToString(nonce)})
	if err != nil {
		return "", err
	}
	message := header + "." + base64.RawURLEncoding.EncodeToString(payload)
	digest := sha256.Sum256([]byte(message))
	signature, err := rsa.SignPKCS1v15(rand.Reader, simulator.tokenKey, crypto.SHA256, digest[:])
	if err != nil {
		return "", err
	}
	return message + "." + base64.RawURLEncoding.EncodeToString(signature), nil
}

func (simulator *Simulator) verifyService(request *http.Request) error {
	match := signatureRE.FindStringSubmatch(request.Header.Get("Authorization"))
	if match == nil || !strings.HasPrefix(match[2], "ST$") {
		return errors.New("missing instance-principal token")
	}
	token := strings.TrimPrefix(match[2], "ST$")
	simulator.mu.Lock()
	session, exists := simulator.sessions[token]
	simulator.mu.Unlock()
	if !exists || !simulator.now().Before(session.expires) {
		return errors.New("unknown or expired instance-principal token")
	}
	return verifySignature(request, nil, session.public, match[2], "date (request-target) host", true, simulator.now())
}

func VerifyPacketImageReceipt(packet VerifiedPacket, imageWire, delegationWire []byte,
	roots trust.Keyring, imageOCID string, runNow time.Time,
) (release.VerifiedImage, error) {
	binary, err := packet.Executable()
	if err != nil {
		return release.VerifiedImage{}, fmt.Errorf("read packet executable: %w", err)
	}
	if binary.GuestPath != "/usr/local/bin/terrascale-orchestrator" || binary.Mode != 0o755 ||
		imageOCID == "" || runNow.IsZero() {
		return release.VerifiedImage{}, errors.New("image verification lacks fixed binary destination, image identity, or clock")
	}
	image, err := release.VerifyImageCurrent(imageWire, delegationWire, roots,
		release.ImageExpectation{Environment: "production", LogicalRegion: "GRU",
			OCIImageOCID: imageOCID, Architecture: binary.Architecture}, runNow)
	if err != nil {
		return release.VerifiedImage{}, fmt.Errorf("verify current image receipt: %w", err)
	}
	receipt := image.Receipt()
	digest := sha256.Sum256(binary.Body)
	if receipt.BinaryBytes != int64(len(binary.Body)) || receipt.BinaryBytes != packet.manifest.Binary.Size ||
		receipt.BinarySHA256 != hex.EncodeToString(digest[:]) || receipt.BinarySHA256 != binary.SHA256 {
		return release.VerifiedImage{}, errors.New("signed image receipt does not bind exact packet executable")
	}
	return image, nil
}

// VerifyPacketEmbeddedImage reads the two fixed host-side release proof files
// from the validated packet and rechecks their signed file digests before
// trusting them. The runtime driver must use this proof and install the bytes
// returned by Executable at its fixed guest path.
func VerifyPacketEmbeddedImage(packet VerifiedPacket, roots trust.Keyring, imageOCID string,
	runNow time.Time,
) (release.VerifiedImage, error) {
	if packet.root == "" {
		return release.VerifiedImage{}, errors.New("packet was not verified")
	}
	read := func(name string) ([]byte, error) {
		var entry *FileEntry
		for index := range packet.manifest.Files {
			if packet.manifest.Files[index].Path == name {
				entry = &packet.manifest.Files[index]
				break
			}
		}
		if entry == nil {
			return nil, fmt.Errorf("packet lacks signed release proof %q", name)
		}
		full := filepath.Join(packet.root, filepath.FromSlash(name))
		info, err := os.Lstat(full)
		if err != nil || !info.Mode().IsRegular() {
			return nil, fmt.Errorf("packet release proof is nonregular: %q", name)
		}
		body, err := os.ReadFile(full)
		if err != nil {
			return nil, err
		}
		digest := sha256.Sum256(body)
		if int64(len(body)) != entry.Size || hex.EncodeToString(digest[:]) != entry.SHA256 {
			return nil, fmt.Errorf("packet release proof changed: %q", name)
		}
		return body, nil
	}
	imageWire, err := read("simulator/release-image-receipt.json")
	if err != nil {
		return release.VerifiedImage{}, err
	}
	delegationWire, err := read("simulator/release-delegation.json")
	if err != nil {
		return release.VerifiedImage{}, err
	}
	return VerifyPacketImageReceipt(packet, imageWire, delegationWire, roots, imageOCID, runNow)
}

func qualifyHistoryImageFixture(t *testing.T, image release.ImageReceipt, environment string, root ed25519.PrivateKey, at time.Time, lifetime time.Duration) release.ImageReceipt {
	t.Helper()
	record := release.ProductionQualification{Schema: release.ProductionQualificationSchema,
		Candidate: release.ProductionExpectation{SourceRevision: image.SourceRevision, ArtifactSHA256: image.ImageSHA256,
			QualificationSHA256: image.QualificationSHA256, Cell: image.OCIRegion, Environment: environment,
			Runtime: release.ProductionRuntime, Architecture: image.Architecture, Role: "orchestrator"}}
	for _, gate := range []string{"runtime-ha", "workload-safety"} {
		evidence := []byte("test-only " + gate + " image evidence")
		record.Evidence = append(record.Evidence, release.ProductionGateEvidence{Gate: gate,
			SHA256: historyDigest(evidence), Bytes: int64(len(evidence)), CompletedAt: at.Add(-time.Second)})
	}
	payload, err := trust.EncodePayload(record)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := trust.Sign(payload, release.ProductionQualificationScope(record.Candidate), at, at.Add(lifetime), root)
	if err != nil {
		t.Fatal(err)
	}
	image.Production = &release.ProductionProof{Qualification: historyTestEnvelope(t, proof)}
	return image
}

type OfflinePacketInput struct {
	SourceRoot      string `json:"sourceRoot"`
	Binary          string `json:"binary"`
	BinarySHA256    string `json:"binarySha256"`
	SourceRevision  string `json:"sourceRevision"`
	BaseImage       string `json:"baseImage"`
	BaseSHA256      string `json:"baseSha256"`
	Image           string `json:"image"`
	ImageSHA256     string `json:"imageSha256"`
	Kernel          string `json:"kernel"`
	KernelSHA256    string `json:"kernelSha256"`
	ServiceUID      uint32 `json:"serviceUid"`
	ServiceGID      uint32 `json:"serviceGid"`
	Packet          string `json:"packet"`
	RootCertificate string `json:"rootCertificate"`
}

func pinnedFile(t *testing.T, name, expected string) int64 {
	t.Helper()
	file, err := os.Open(name)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() {
		t.Fatalf("input %q is not regular: %v", name, err)
	}
	hash := sha256.New()
	if _, err := io.Copy(hash, file); err != nil {
		t.Fatal(err)
	}
	if hex.EncodeToString(hash.Sum(nil)) != expected {
		t.Fatalf("input %q differs from frozen SHA-256", name)
	}
	return info.Size()
}

func validateProductionBuildInfo(info *debug.BuildInfo, sourceRevision string) error {
	if info == nil {
		return errors.New("production executable has no Go build information")
	}
	settings := make(map[string]string, len(info.Settings))
	for _, setting := range info.Settings {
		settings[setting.Key] = setting.Value
	}
	if info.GoVersion != release.DefaultGoVersion || settings["vcs.revision"] != sourceRevision ||
		settings["vcs.modified"] != "false" || settings["GOOS"] != "linux" ||
		settings["GOARCH"] != "amd64" || settings["CGO_ENABLED"] != "0" {
		return errors.New("production executable build provenance differs from frozen receipt input")
	}
	return nil
}

func TestOfflineIssuerRejectsChangedBuildIdentity(t *testing.T) {
	info, err := buildinfo.ReadFile(os.Args[0])
	if err != nil {
		t.Fatal(err)
	}
	info.GoVersion = release.DefaultGoVersion
	info.Settings = []debug.BuildSetting{{Key: "vcs.revision", Value: "a"},
		{Key: "vcs.modified", Value: "false"}, {Key: "GOOS", Value: "linux"},
		{Key: "GOARCH", Value: "amd64"}, {Key: "CGO_ENABLED", Value: "0"}}
	if err := validateProductionBuildInfo(info, "a"); err != nil {
		t.Fatal(err)
	}
	for _, change := range []struct{ key, value string }{
		{"vcs.revision", "b"}, {"vcs.modified", "true"}, {"CGO_ENABLED", "1"},
	} {
		mutated := *info
		mutated.Settings = append([]debug.BuildSetting(nil), info.Settings...)
		for index := range mutated.Settings {
			if mutated.Settings[index].Key == change.key {
				mutated.Settings[index].Value = change.value
			}
		}
		if err := validateProductionBuildInfo(&mutated, "a"); err == nil {
			t.Fatalf("accepted changed build setting %s=%s", change.key, change.value)
		}
	}
}

func TestEmitOfflineProductionPacket(t *testing.T) {
	// TS_PRODUCTION_PACKET_INPUT names the frozen offline packet input JSON.
	inputPath := tier.Qualification(t, "TS_PRODUCTION_PACKET_INPUT")[0]
	wire, err := os.ReadFile(inputPath)
	if err != nil {
		t.Fatal(err)
	}
	var input OfflinePacketInput
	if err := json.Unmarshal(wire, &input, json.RejectUnknownMembers(true)); err != nil {
		t.Fatal(err)
	}
	binarySize := pinnedFile(t, input.Binary, input.BinarySHA256)
	baseSize := pinnedFile(t, input.BaseImage, input.BaseSHA256)
	imageSize := pinnedFile(t, input.Image, input.ImageSHA256)
	pinnedFile(t, input.Kernel, input.KernelSHA256)
	if binarySize == 0 || baseSize == 0 || imageSize == 0 || input.ServiceUID == 0 || input.ServiceGID == 0 {
		t.Fatal("offline image, binary, or service ownership is absent")
	}
	info, err := buildinfo.ReadFile(input.Binary)
	if err != nil || info == nil {
		t.Fatalf("read production executable build information: %v", err)
	}
	if err := validateProductionBuildInfo(info, input.SourceRevision); err != nil {
		t.Fatal(err)
	}
	binary, err := os.ReadFile(input.Binary)
	if err != nil {
		t.Fatal(err)
	}
	// A matching artifact SHA-256 is required before the receipt is signed.
	if int64(len(binary)) != binarySize {
		t.Fatal("binary changed between pinning and receipt construction")
	}
	now := time.Now().UTC().Truncate(time.Second)
	qualificationDigest := sha256.Sum256([]byte("offline qualification fixture"))
	receipt := release.ImageReceipt{Schema: release.ImageSchema,
		SourceRevision: input.SourceRevision, GoVersion: release.DefaultGoVersion,
		Architecture: "amd64", BinaryBytes: binarySize, BinarySHA256: input.BinarySHA256,
		QualificationSHA256: hex.EncodeToString(qualificationDigest[:]),
		BaseImageOCID:       "ocid1.image.oc1.sa-saopaulo-1.offline-base-fixture",
		BaseImageRegion:     "GRU", BaseImageSHA256: input.BaseSHA256,
		KernelRelease: "6.1.186", KernelSHA256: input.KernelSHA256,
		ImageFormat: "qcow2", ImageBytes: imageSize, ImageSHA256: input.ImageSHA256,
		OCIImageOCID: "ocid1.image.oc1.sa-saopaulo-1.offline-production-restart",
		OCIRegion:    "GRU"}
	if err := receipt.Validate(); err != nil {
		t.Fatal(err)
	}
	inputs := productionGuestTestInputs(t, now, binary)
	inputs.ServiceUID, inputs.ServiceGID = input.ServiceUID, input.ServiceGID
	recipe := signedHistoryRecipeWithMaterialsAndReceipt(t, now, binary, inputs.Credentials, &receipt)
	capture, err := NewCapturingObjectStorage(now)
	if err != nil {
		t.Fatal(err)
	}
	pins, err := CurrentCompletedSourcePins(input.SourceRoot)
	if err != nil {
		t.Fatal(err)
	}
	anchor := recipe.Anchor.Anchor()
	manifest := Manifest{SchemaVersion: ManifestVersion, DeploymentID: anchor.DeploymentID,
		Cell: string(anchor.Cell), Environment: anchor.Environment, FixtureNow: now,
		Binary: BinaryInput{Path: "input/orchestrator", GuestPath: "/usr/local/bin/terrascale-orchestrator",
			Architecture: "amd64"}, SourcePins: pins}
	for _, slot := range anchor.ControllerSlots {
		manifest.Controllers = append(manifest.Controllers, Controller{Slot: slot,
			InstanceOCID: recipe.Observed[slot].InstanceOCID,
			GuestRoot:    "controllers/" + slot + "/guest-root"})
	}
	compute, err := BuildComputeInventory(recipe, inputs)
	if err != nil {
		t.Fatal(err)
	}
	manifest.Routes = compute.Routes
	packet, _, err := EmitCompletedRestartPacket(t.Context(), input.Packet, input.SourceRoot,
		manifest, func(ctx context.Context, completed CompletedHistories) (map[string][]byte, error) {
			material, err := BuildVerifiedGuestMaterial(ctx, recipe, completed, inputs)
			if err != nil {
				return nil, err
			}
			for name, body := range compute.Bodies {
				material[name] = bytes.Clone(body)
			}
			return material, nil
		}, recipe.Anchor, capture, recipe.Prepare, recipe.RootPrivateKey, recipe.Roots, now.Add(2*time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	der, err := x509.MarshalPKIXPublicKey(recipe.RootPrivateKey.Public())
	if err != nil {
		t.Fatal(err)
	}
	root := pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: der})
	if err := os.MkdirAll(filepath.Dir(input.RootCertificate), 0o700); err != nil {
		t.Fatal(err)
	}
	file, err := os.OpenFile(input.RootCertificate, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := file.Write(root); err != nil {
		file.Close()
		t.Fatal(err)
	}
	if err := file.Close(); err != nil {
		t.Fatal(err)
	}
	t.Logf("offline packet %s; root %s; image %s", input.Packet, input.RootCertificate,
		packet.Manifest().Binary.SHA256)
}

// Qualifying reports whether this run is a T2 qualification run.
func Qualifying() bool { return os.Getenv(Env) == QualificationTier }

// Integration marks a T1 test: a multi-process lab or a slow end-to-end
// contract whose invariants T0 already covers with a single-process test.
// It skips under go test -short.
func Integration(t testing.TB) {
	t.Helper()
	if testing.Short() {
		t.Skip("integration tier: runs without -short on pushes to develop and main")
	}
}

// Qualification marks a T2 test that needs real infrastructure named by
// environment variables, and returns their values in order. When any of them
// is unset or empty the test skips, except in a qualification run, where it
// fails: the fixture the gate promised is missing.
func Qualification(t testing.TB, envs ...string) []string {
	t.Helper()
	if len(envs) == 0 {
		t.Fatal("tier.Qualification needs the environment variables that supply its fixture")
	}
	values := make([]string, len(envs))
	var missing []string
	for i, name := range envs {
		values[i] = os.Getenv(name)
		if values[i] == "" {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		Unavailable(t, "qualification fixture not supplied: set %s", strings.Join(missing, ", "))
	}
	return values
}

// Unavailable reports that a T2 fixture is missing for a reason the caller
// determined itself, such as an opt-in that needs one of several variables.
// It skips the test, or fails it in a qualification run.
func Unavailable(t testing.TB, format string, args ...any) {
	t.Helper()
	if Qualifying() {
		t.Fatalf(Env+"="+QualificationTier+": "+format, args...)
	}
	t.Skipf(format, args...)
}
